insert into kafaa_research_challenges (id, title_en, title_ar, theme, summary_en, summary_ar, status, is_published, screening_signed_by, screening_signed_at, security_ok, export_control_ok, closes_on) values
('rc-1', 'Arabic-first technical learning content', 'محتوى تعليمي تقني يبدأ بالعربية', 'Learning', 'How might we produce reviewed Arabic-first learning content for nuclear fundamentals at scale?', 'كيف يمكننا إنتاج محتوى تعليمي مراجَع يبدأ بالعربية لأساسيات الطاقة النووية على نطاق واسع؟', 'published', true, 'p-k-admin', '2026-08-01T08:00:00Z', true, true, '2027-01-31'),
('rc-2', 'Heat-stress management for outdoor work', 'إدارة الإجهاد الحراري للعمل في الهواء الطلق', 'Health & safety', 'Practical, evidence-based approaches to heat-stress controls in summer outages.', 'مناهج عملية قائمة على الأدلة لضوابط الإجهاد الحراري في فترات الإيقاف الصيفية.', 'published', true, 'p-k-admin', '2026-08-01T08:00:00Z', true, true, '2027-01-31'),
('rc-3', 'Coral restoration monitoring', 'رصد استعادة الشعاب المرجانية', 'Environment', 'Low-cost monitoring methods for coral cultivation programmes.', 'طرق رصد منخفضة التكلفة لبرامج استزراع المرجان.', 'published', true, 'p-k-admin', '2026-08-01T08:00:00Z', true, true, '2027-01-31'),
('rc-4', 'Simulator scenario authoring tools', 'أدوات تأليف سيناريوهات المحاكي', 'Training', 'Tools that help instructors author and version simulator scenarios.', 'أدوات تساعد المدربين على تأليف سيناريوهات المحاكي وإدارة إصداراتها.', 'screening', false, null, null, false, false, '2027-01-31'),
('rc-5', 'Advanced reactor workforce models', 'نماذج القوى العاملة للمفاعلات المتقدمة', 'Future workforce', 'Draft problem statement.', 'بيان مشكلة (مسودة).', 'draft', false, null, null, false, false, '2027-01-31')
