('rp-2', 'rc-2', 'ku', 'Wearable heat-stress sensing pilot', 'Pilot with consenting volunteers; no plant data.', 'screening', 'MoET patents route (May 2026 MoU)', true, '2026-09-24T08:00:00Z'),
('rp-3', 'rc-3', 'src', 'Remote coral monitoring with low-cost sensors', 'SRC/GIEMS capacity-building track.', 'draft', 'MoET patents route (May 2026 MoU)', false, null),
('rp-4', null, 'org-alnoor', 'Localised manufacture of pump wear rings', 'Supplier-led proposal; IP routed via the MoET patents route.', 'submitted', 'MoET patents route (May 2026 MoU)', false, '2026-09-24T08:00:00Z')
