insert into kafaa_sc_traits (id, n, name_en, name_ar, description_en, description_ar, behaviours, prompts) values
('trait-1', 1, 'Personal accountability', 'المساءلة الشخصية', 'All individuals take personal responsibility for safety.', 'يتحمل كل فرد المسؤولية الشخصية عن السلامة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"personal accountability\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"المساءلة الشخصية\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-2', 2, 'Questioning attitude', 'موقف التساؤل', 'Individuals avoid complacency and challenge existing conditions and assumptions.', 'يتجنب الأفراد التهاون ويتحدّون الظروف والافتراضات القائمة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"questioning attitude\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"موقف التساؤل\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-3', 3, 'Effective safety communication', 'التواصل الفعال بشأن السلامة', 'Communications maintain a focus on safety.', 'يحافظ التواصل على التركيز على السلامة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"effective safety communication\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"التواصل الفعال بشأن السلامة\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-4', 4, 'Leadership safety values and actions', 'قيم وأفعال القيادة في مجال السلامة', 'Leaders demonstrate a commitment to safety in decisions and behaviours.', 'يُظهر القادة التزامهم بالسلامة في قراراتهم وسلوكهم.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"leadership safety values and actions\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"قيم وأفعال القيادة في مجال السلامة\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-5', 5, 'Decision-making', 'اتخاذ القرار', 'Decisions that support or affect nuclear safety are systematic, rigorous and thorough.', 'تكون القرارات المتعلقة بالسلامة النووية منهجية ودقيقة وشاملة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"decision-making\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"اتخاذ القرار\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-6', 6, 'Respectful work environment', 'بيئة عمل محترمة', 'Trust and respect permeate the organisation.', 'تسود الثقة والاحترام في أرجاء المؤسسة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"respectful work environment\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"بيئة عمل محترمة\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-7', 7, 'Continuous learning', 'التعلم المستمر', 'Opportunities to learn are valued, sought out and implemented.', 'تُقدَّر فرص التعلم ويُسعى إليها وتُطبَّق.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"continuous learning\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"التعلم المستمر\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-8', 8, 'Problem identification and resolution', 'تحديد المشكلات وحلها', 'Issues potentially affecting safety are promptly identified, evaluated and corrected.', 'تُحدَّد القضايا التي قد تؤثر في السلامة وتُقيَّم وتُصحَّح بسرعة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"problem identification and resolution\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"تحديد المشكلات وحلها\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-9', 9, 'Environment for raising concerns', 'بيئة رفع المخاوف', 'A safety-conscious work environment where people feel free to raise concerns without fear of retaliation.', 'بيئة عمل واعية بالسلامة يشعر فيها الناس بحرية رفع المخاوف دون خوف من الانتقام.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"environment for raising concerns\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"بيئة رفع المخاوف\" أحدثت فرقاً في عمل ما؟"}]'::jsonb),
('trait-10', 10, 'Work processes', 'عمليات العمل', 'Work activities are planned and controlled so that safety is maintained.', 'تُخطَّط أنشطة العمل وتُضبط بما يحافظ على السلامة.', '[{"en":"What it looks like on shift: one observable behaviour, discussed in team briefs.","ar":"كيف تبدو في النوبة: سلوك واحد قابل للملاحظة يُناقش في إحاطات الفريق."}]'::jsonb, '[{"en":"When did you last see \"work processes\" make a difference to a job?","ar":"متى رأيت آخر مرة أن \"عمليات العمل\" أحدثت فرقاً في عمل ما؟"}]'::jsonb)
insert into kafaa_hu_tools (id, name_en, name_ar, description_en, description_ar, kind) values
('hu-1', 'Self-checking (STAR)', 'التحقق الذاتي (STAR)', 'Stop, Think, Act, Review before and after each action.', 'توقف، فكّر، نفّذ، راجع قبل كل إجراء وبعده.', 'core'),
('hu-2', 'Three-way communication', 'الاتصال الثلاثي', 'Sender states, receiver repeats back, sender confirms.', 'يصرّح المرسل ويكرر المستلم ويؤكد المرسل.', 'core'),
('hu-3', 'Procedure use and adherence', 'استخدام الإجراءات والالتزام بها', 'Use the right procedure at the right level of use; stop when it cannot be followed.', 'استخدم الإجراء الصحيح بمستوى الاستخدام المناسب وتوقف عند تعذر اتباعه.', 'core'),
('hu-4', 'Pre-job brief', 'إحاطة ما قبل العمل', 'Critical steps, error traps and contingencies, graded to risk.', 'الخطوات الحرجة ومصائد الأخطاء والخطط البديلة متدرجة حسب المخاطر.', 'core'),
('hu-5', 'Questioning attitude', 'موقف التساؤل', 'Stop when unsure.', 'توقف عند الشك.', 'core'),
('hu-6', 'Peer checking', 'التحقق من الزميل', 'A co-worker confirms the intended action before it is taken.', 'يؤكد زميل الإجراء المقصود قبل تنفيذه.', 'conditional'),
('hu-7', 'Independent verification', 'التحقق المستقل', 'A second qualified person checks separately, in time and action.', 'يتحقق شخص مؤهل ثانٍ بشكل منفصل زمناً وفعلاً.', 'conditional'),
('hu-8', 'Place-keeping', 'تتبع الموضع', 'Mark steps as completed to avoid omissions.', 'تعليم الخطوات المنجزة لتجنب السهو.', 'conditional')
insert into kafaa_oe_lessons (id, title_en, title_ar, summary_en, summary_ar, lesson_en, lesson_ar, source_kind, trait_ids, reviewed_on, reviewing_body, deidentified, status, affected_standard_ids, sample) values
('oe-1', 'Wrong-train work prevented by a peer check', 'منع العمل على المسار الخطأ بفضل التحقق من الزميل', 'A technician prepared to work on the wrong redundant train; a peer check caught it.', 'استعد فني للعمل على المسار الاحتياطي الخطأ، وكشف التحقق من الزميل ذلك.', 'Use component labels and peer checks on redundant equipment.', 'استخدم ملصقات المكونات والتحقق من الزميل على المعدات الاحتياطية.', 'WANO', array['trait-2','trait-10']::text[], '2026-01-15', 'OE Screening Committee', true, 'published', array['qs-mech']::text[], true),
('oe-2', 'Procedure step skipped under time pressure', 'تخطي خطوة إجرائية تحت ضغط الوقت', 'An industry event where a step was missed during a time-pressured evolution.', 'حدث في القطاع فاتت فيه خطوة خلال عملية تحت ضغط الوقت.', 'Place-keeping and stopping when rushed.', 'تتبع الموضع والتوقف عند الاستعجال.', 'INPO', array['trait-1','trait-5']::text[], '2026-02-15', 'OE Screening Committee', true, 'published', array['qs-lo-turbine']::text[], true),
('oe-3', 'Standing alarms and operator burden', 'الإنذارات الدائمة وعبء المشغّل', 'Lessons from managing standing control room alarms (a 2021 FANR finding at Unit 1 was closed in Dec 2023).', 'دروس من إدارة إنذارات غرفة التحكم الدائمة (أُغلقت ملاحظة للهيئة من 2021 في الوحدة 1 في ديسمبر 2023).', 'Treat standing alarms as problems to resolve, not background.', 'تعامل مع الإنذارات الدائمة كمشكلات يجب حلها لا كخلفية.', 'internal', array['trait-8']::text[], '2026-03-15', 'OE Screening Committee', true, 'published', array['qs-ro','qs-sro']::text[], true),
('oe-4', 'Foreign material found during an outage', 'العثور على مواد غريبة خلال فترة إيقاف', 'A generic industry lesson on foreign material exclusion.', 'درس عام من القطاع حول منع دخول المواد الغريبة.', 'FME controls apply to every open system.', 'تنطبق ضوابط منع المواد الغريبة على كل نظام مفتوح.', 'EPRI', array['trait-10']::text[], '2026-04-15', 'OE Screening Committee', true, 'published', array['qs-mech']::text[], true),
('oe-5', 'Contamination from an unsurveyed tool', 'تلوث من أداة غير ممسوحة', 'A generic lesson on tool control in contaminated areas.', 'درس عام حول التحكم في الأدوات في المناطق الملوثة.', 'Survey tools before release.', 'امسح الأدوات قبل إخراجها.', 'IAEA IRS', array['trait-7']::text[], '2026-05-15', 'OE Screening Committee', true, 'published', array['qs-rp']::text[], true),
('oe-6', 'Supplier certificate mismatch caught at receiving', 'كشف عدم تطابق شهادة المورد عند الاستلام', 'Heat numbers missing from a material certificate were caught at receipt inspection.', 'كُشف غياب أرقام الصهر من شهادة مادة عند فحص الاستلام.', 'Verify certificates against the item, not the paperwork alone.', 'تحقق من الشهادات مقابل المادة لا الورق وحده.', 'internal', array['trait-2','trait-8']::text[], '2026-06-15', 'OE Screening Committee', true, 'published', '{}'::text[], true)
insert into kafaa_ecp_channels (id, kind, label_en, label_ar, detail_en, detail_ar, sort, source) values
('ecp-office', 'office', 'ECP offices', 'مكاتب برنامج مخاوف الموظفين', 'Confidential, independent offices on site.', 'مكاتب سرية ومستقلة في الموقع.', 1, 'SR2024 p.86-87; CNS report'),
('ecp-intranet', 'intranet', 'ECP intranet portal', 'بوابة البرنامج على الشبكة الداخلية', 'Available on the ENEC intranet (not in Kafa''a).', 'متاحة على الشبكة الداخلية لـENEC (ليست في كفاءة).', 2, 'SR2024 p.86-87; CNS report'),
('ecp-phone', 'phone', '24/7 phone line', 'خط هاتف على مدار الساعة', 'A confidential line answered at any time.', 'خط سري يُجاب في أي وقت.', 3, 'SR2024 p.86-87; CNS report'),
('ecp-email', 'email', 'ECP email', 'البريد الإلكتروني للبرنامج', 'A monitored, confidential mailbox.', 'صندوق بريد سري ومراقَب.', 4, 'SR2024 p.86-87; CNS report'),
('ecp-reps', 'reps', 'Unit representatives', 'ممثلو الوحدات', 'Representatives at Units 1&2 and 3&4.', 'ممثلون في الوحدتين 1 و2 والوحدتين 3 و4.', 5, 'SR2024 p.86-87; CNS report'),
('ecp-r2p', 'r2p', 'FANR Report to Protect (R2P)', 'نظام "أبلغ لتحمي" لدى الهيئة', 'An external option run by the regulator.', 'خيار خارجي تديره الجهة الرقابية.', 6, 'SR2024 p.86-87; CNS report')
