insert into kafaa_adv_technologies (id, family_en, family_ar, partners_en, partners_ar, designs, skill_areas_en, skill_areas_ar, mou_date, sources, sort) values
('tech-bwr', 'Small boiling water reactor', 'مفاعل الماء المغلي الصغير', 'GE Hitachi / GE Vernova Hitachi; ORLEN Synthos Green Energy framework', 'جي إي هيتاشي / جي إي فيرنوفا هيتاشي؛ إطار أورلين سينثوس', 'BWRX-300', 'BWR plant systems and chemistry; new licensing basis', 'أنظمة مفاعلات الماء المغلي وكيمياؤها؛ أساس ترخيص جديد', 'Dec 2023, May 2025', '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"},{"id":"wnn-gevh","label":"WNN · MoU on international BWRX-300 deployment (May 2025)","url":"https://www.world-nuclear-news.org/articles/mou-paves-way-for-further-collaboration-on-bwrx-300-deployment"},{"id":"wnn-osge","label":"WNN · ENEC and OSGE cooperate to advance SMRs","url":"https://www.world-nuclear-news.org/articles/enec,-osge-cooperate-to-advance-smrs"}]'::jsonb, 1),
('tech-htgr', 'High-temperature gas-cooled', 'المفاعلات عالية الحرارة المبرّدة بالغاز', 'X-energy; CNNC (HTGR MoU)', 'إكس-إنرجي؛ المؤسسة الصينية (مذكرة HTGR)', 'Xe-100', 'Gas coolant systems, different fuel form, high-temperature process heat', 'أنظمة التبريد بالغاز وشكل وقود مختلف وحرارة عمليات عالية', 'Dec 2023', '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"}]'::jsonb, 2),
('tech-fast', 'Fast reactors with liquid-metal coolant', 'المفاعلات السريعة المبرّدة بالمعادن السائلة', 'TerraPower; Newcleo', 'تيراباور؛ نيوكليو', 'Natrium; lead-cooled fast reactor', 'Liquid-metal handling and chemistry, fast-spectrum physics', 'مناولة المعادن السائلة وكيمياؤها وفيزياء الطيف السريع', 'Dec 2023, Feb 2025', '[{"id":"wnn-advance","label":"WNN · ENEC to evaluate deployment of SMRs and microreactors (ADVANCE)","url":"https://world-nuclear-news.org/articles/enec-to-evaluate-deployment-of-smrs-and-microreact"},{"id":"wnn-newcleo","label":"WNN · Newcleo teams up with ENEC (Feb 2025)","url":"https://www.world-nuclear-news.org/articles/newcleo-teams-up-with-enec-for-international-projects"}]'::jsonb, 3),
('tech-micro', 'Microreactors', 'المفاعلات المتناهية الصغر', 'Westinghouse; USNC (assets now with NANO Nuclear)', 'وستنجهاوس؛ يو إس إن سي (أصولها لدى نانو نيوكلير)', 'eVinci; MMR', 'Remote and autonomous operation concepts, transportable units', 'مفاهيم التشغيل عن بعد والتشغيل الذاتي والوحدات القابلة للنقل', 'Dec 2023', '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"}]'::jsonb, 4),
('tech-msr', 'Molten salt', 'مفاعلات الأملاح المنصهرة', 'MoltexFLEX', 'مولتكس فلكس', 'FLEX', 'Salt chemistry and materials', 'كيمياء الأملاح والمواد', 'Dec 2023', '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"}]'::jsonb, 5),
('tech-intl', 'International projects', 'المشاريع الدولية', 'Westinghouse (AP1000 US MoU); Samsung C&T; KEPCO (SMR, AI, digital twins)', 'وستنجهاوس (مذكرة AP1000)؛ سامسونج سي آند تي؛ كيبكو', 'AP1000 and others', 'Project delivery abroad, investment and owner''s-engineer skills (ENEC Consulting)', 'تنفيذ المشاريع في الخارج والاستثمار ومهارات مهندس المالك', 'Jul 2025, Nov 2025', '[{"id":"admo-westinghouse","label":"Abu Dhabi Media Office · ENEC and Westinghouse agreement (Jul 2025)","url":"https://www.mediaoffice.abudhabi/en/energy/emirates-nuclear-energy-company-and-westinghouse-electric-company-sign-agreement-to-accelerate-nuclear-energy-solutions-in-the-us/"},{"id":"enec-samsung","label":"ENEC · Samsung C&T MoU (Jul 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-samsung-candt-sign-mou-to-advance-global-nuclear-energy-collaboration/"},{"id":"wnn-kepco-2025","label":"WNN · KEPCO and ENEC enhance cooperation (Nov 2025)","url":"https://www.world-nuclear-news.org/articles/kepco-and-enec-enhance-cooperation-in-nuclear-energy"}]'::jsonb, 6)
insert into kafaa_skill_bridges (id, from_role_id, tech_id, transfers_en, transfers_ar, new_en, new_ar) values
