insert into kafaa_future_roles (id, tech_ids, title_en, title_ar, summary_en, summary_ar, from_role_ids, skill_ids, horizon, family_id, sort) values
('fr-bwr-operator', array['tech-bwr']::text[], 'Small BWR operator (concept)', 'مشغّل مفاعل ماء مغلي صغير (مفهوم)', 'A licensed-operator path for a small boiling water reactor, building on APR-1400 conduct of operations.', 'مسار مشغّل مرخّص لمفاعل ماء مغلي صغير يبني على إدارة العمليات في APR-1400.', array['reactor-operator','senior-reactor-operator']::text[], array['as-conduct-of-ops','as-bwr-systems','as-passive-safety']::text[], 'explore', 'operations', 1),
('fr-remote-ops', array['tech-micro']::text[], 'Microreactor remote operations specialist (concept)', 'أخصائي التشغيل عن بعد للمفاعلات المتناهية الصغر (مفهوم)', 'Monitors factory-built units from a central room and oversees autonomous control functions.', 'يراقب الوحدات المصنّعة في المصنع من غرفة مركزية ويشرف على وظائف التحكم الذاتي.', array['reactor-operator','cyber-security-engineer']::text[], array['as-remote-ops','as-autonomous-control']::text[], 'watch', 'operations', 2),
('fr-liquid-metal', array['tech-fast']::text[], 'Liquid-metal systems engineer (concept)', 'مهندس أنظمة المعادن السائلة (مفهوم)', 'Designs and supports systems that handle sodium or lead coolants.', 'يصمم الأنظمة التي تتعامل مع مبرّدات الصوديوم أو الرصاص ويدعمها.', array['systems-design-plant-engineer','maintenance-technician-engineer']::text[], array['as-liquid-metal','as-opaque-inspection']::text[], 'watch', 'engineering', 3),
('fr-salt-chemist', array['tech-msr']::text[], 'Molten salt chemistry specialist (concept)', 'أخصائي كيمياء الأملاح المنصهرة (مفهوم)', 'Controls salt chemistry and corrosion in molten salt systems.', 'يضبط كيمياء الأملاح والتآكل في أنظمة الأملاح المنصهرة.', array['chemistry-technician']::text[], array['as-salt-chemistry','as-salt-materials','as-lab-qa']::text[], 'watch', 'chemistry', 4),
('fr-ht-materials', array['tech-htgr','tech-msr']::text[], 'High-temperature materials engineer (concept)', 'مهندس المواد عالية الحرارة (مفهوم)', 'Qualifies graphite, alloys and coatings for high-temperature service.', 'يؤهل الغرافيت والسبائك والطلاءات للخدمة في درجات حرارة عالية.', array['systems-design-plant-engineer','quality-assurance-qc']::text[], array['as-graphite','as-salt-materials']::text[], 'watch', 'engineering', 5),
('fr-adv-fuel', array['tech-htgr','tech-fast']::text[], 'Advanced fuel specialist (concept)', 'أخصائي الوقود المتقدم (مفهوم)', 'Works on coated-particle and fast-reactor fuel forms and their supply chains.', 'يعمل على أشكال الوقود ذي الجسيمات المغلفة ووقود المفاعلات السريعة وسلاسل إمدادها.', array['nuclear-fuel-specialist','reactor-engineer-core-physicist']::text[], array['as-triso-fuel','as-fast-physics']::text[], 'explore', 'nuclear-fuel', 6),
('fr-adv-licensing', array['tech-bwr','tech-htgr','tech-fast','tech-micro','tech-msr']::text[], 'Advanced reactor licensing specialist (concept)', 'أخصائي ترخيص المفاعلات المتقدمة (مفهوم)', 'Builds a licensing basis for a new design with the regulator; no proposal has been made to FANR.', 'يبني أساس الترخيص لتصميم جديد مع الجهة الرقابية؛ ولم يُقدَّم أي مقترح إلى الهيئة.', array['regulatory-affairs-licensing-engineer']::text[], array['as-new-licensing-basis','as-other-regulators']::text[], 'explore', 'licensing', 7),
('fr-owners-engineer', array['tech-intl']::text[], 'Owner''s engineer, international projects (concept)', 'مهندس المالك للمشاريع الدولية (مفهوم)', 'Represents the owner on projects abroad, in line with ENEC Consulting''s advisory work.', 'يمثل المالك في المشاريع الخارجية بما يتماشى مع العمل الاستشاري لـENEC للاستشارات.', array['systems-design-plant-engineer','procurement-engineer','outage-manager-planner']::text[], array['as-owners-engineer','as-project-abroad','as-investment-appraisal']::text[], 'prepare', 'engineering', 8),
('fr-digital-twin', array['tech-intl','tech-micro']::text[], 'Digital twin engineer (concept)', 'مهندس التوائم الرقمية (مفهوم)', 'Builds and governs digital twins, separate from reactor control systems.', 'يبني التوائم الرقمية ويحوكمها بمعزل عن أنظمة التحكم في المفاعل.', array['systems-design-plant-engineer','cyber-security-engineer']::text[], array['as-digital-twins','as-remote-ops']::text[], 'prepare', 'engineering', 9),
('fr-process-heat', array['tech-htgr']::text[], 'Process-heat integration engineer (concept)', 'مهندس دمج حرارة العمليات (مفهوم)', 'Studies how high-temperature heat could serve industrial users; exploratory only.', 'يدرس كيف يمكن لحرارة العمليات العالية أن تخدم المستخدمين الصناعيين؛ استكشافي فقط.', array['systems-design-plant-engineer']::text[], array['as-process-heat']::text[], 'watch', 'engineering', 10),
('fr-adv-instructor', array['tech-bwr','tech-htgr','tech-fast','tech-micro','tech-msr']::text[], 'Advanced reactor instructor (concept)', 'مدرّب المفاعلات المتقدمة (مفهوم)', 'Teaches advanced reactor fundamentals to staff and students using the systematic approach to training.', 'يدرّس أساسيات المفاعلات المتقدمة للموظفين والطلاب وفق النهج المنهجي للتدريب.', array['nuclear-training-instructor']::text[], array['as-reactivity','as-passive-safety']::text[], 'prepare', 'training', 11)
insert into kafaa_adv_tracks (id, title_en, title_ar, summary_en, summary_ar, audience, level, tech_ids, modules, course_id, hours, sources, sort) values
('trk-orientation', 'Advanced reactor families: an orientation', 'عائلات المفاعلات المتقدمة: مدخل تعريفي', 'What the ADVANCE programme evaluates, the six technology families and what changes from APR-1400.', 'ما يقيّمه برنامج ADVANCE، والعائلات التقنية الست، وما الذي يتغير عن APR-1400.', 'all', 'intro', array['tech-bwr','tech-htgr','tech-fast','tech-micro','tech-msr','tech-intl']::text[], '[{"en":"What ADVANCE evaluates","ar":"ما يقيّمه برنامج ADVANCE","minutes":40},{"en":"Six technology families compared","ar":"مقارنة بين العائلات التقنية الست","minutes":60},{"en":"What transfers from APR-1400","ar":"ما الذي ينتقل من APR-1400","minutes":40},{"en":"Knowledge check","ar":"اختبار المعرفة","minutes":20}]'::jsonb, 'c-adv-intro', 3, '[{"id":"wnn-advance","label":"WNN · ENEC to evaluate deployment of SMRs and microreactors (ADVANCE)","url":"https://world-nuclear-news.org/articles/enec-to-evaluate-deployment-of-smrs-and-microreact"},{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"}]'::jsonb, 1),
('trk-smr-ops', 'SMRs and microreactors: what changes for operators', 'المفاعلات الصغيرة والمتناهية الصغر: ما الذي يتغير للمشغّلين', 'Passive safety, remote and autonomous operation concepts and new licensing questions.', 'السلامة الخاملة ومفاهيم التشغيل عن بعد وأسئلة الترخيص الجديدة.', 'staff', 'intermediate', array['tech-bwr','tech-micro']::text[], '[{"en":"Passive safety and natural circulation","ar":"السلامة الخاملة والدوران الطبيعي","minutes":60},{"en":"Remote and autonomous operation concepts","ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي","minutes":60},{"en":"Licensing a new design","ar":"ترخيص تصميم جديد","minutes":60},{"en":"Case discussion","ar":"مناقشة حالة","minutes":60}]'::jsonb, 'c-adv-smr', 4, '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"},{"id":"wnn-gevh","label":"WNN · MoU on international BWRX-300 deployment (May 2025)","url":"https://www.world-nuclear-news.org/articles/mou-paves-way-for-further-collaboration-on-bwrx-300-deployment"}]'::jsonb, 2),
('trk-students', 'Advanced reactors for students', 'المفاعلات المتقدمة للطلاب', 'A short introduction for school and university students: coolants, fuels and the careers that grow from today''s roles.', 'مقدمة قصيرة لطلاب المدارس والجامعات: المبرّدات والوقود والمهن التي تنمو من الأدوار الحالية.', 'students', 'intro', array['tech-htgr','tech-fast','tech-msr']::text[], '[{"en":"How a reactor makes heat","ar":"كيف يولّد المفاعل الحرارة","minutes":30},{"en":"Water, gas, metal and salt: coolants compared","ar":"الماء والغاز والمعادن والأملاح: مقارنة المبرّدات","minutes":40},{"en":"Careers that transfer","ar":"مهن قابلة للانتقال","minutes":30}]'::jsonb, null, 1.7, '[{"id":"wnn-advance","label":"WNN · ENEC to evaluate deployment of SMRs and microreactors (ADVANCE)","url":"https://world-nuclear-news.org/articles/enec-to-evaluate-deployment-of-smrs-and-microreact"}]'::jsonb, 3),
('trk-materials', 'Coolants, fuels and materials compared', 'المبرّدات والوقود والمواد: مقارنة', 'Chemistry and materials questions that differ from pressurised water reactors.', 'أسئلة الكيمياء والمواد التي تختلف عن مفاعلات الماء المضغوط.', 'all', 'intermediate', array['tech-htgr','tech-fast','tech-msr']::text[], '[{"en":"Gas coolants and TRISO fuel","ar":"المبرّدات الغازية ووقود TRISO","minutes":45},{"en":"Liquid metals","ar":"المعادن السائلة","minutes":45},{"en":"Molten salts","ar":"الأملاح المنصهرة","minutes":45},{"en":"Materials at high temperature","ar":"المواد في درجات الحرارة العالية","minutes":45}]'::jsonb, null, 3, '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous"},{"id":"wnn-newcleo","label":"WNN · Newcleo teams up with ENEC (Feb 2025)","url":"https://www.world-nuclear-news.org/articles/newcleo-teams-up-with-enec-for-international-projects"}]'::jsonb, 4),
('trk-digital', 'AI and digital twins in nuclear operations', 'الذكاء الاصطناعي والتوائم الرقمية في العمليات النووية', 'Themes ENEC has named: the ENEC-KEPCO AI Innovation Lab and the ENECIQ platform, which runs separately from reactor systems.', 'محاور أعلنتها ENEC: مختبر ابتكار الذكاء الاصطناعي مع كيبكو ومنصة ENECIQ التي تعمل بمعزل عن أنظمة المفاعل.', 'staff', 'intro', array['tech-intl','tech-micro']::text[], '[{"en":"Digital twins: what they are and are not","ar":"التوائم الرقمية: ما هي وما ليست","minutes":40},{"en":"Governed AI at work","ar":"الذكاء الاصطناعي المحوكم في العمل","minutes":40},{"en":"Keeping AI away from reactor control","ar":"إبقاء الذكاء الاصطناعي بعيداً عن التحكم في المفاعل","minutes":30}]'::jsonb, null, 1.8, '[{"id":"enec-presight","label":"ENEC · ENECIQ with Presight (Oct 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-presight-co-develop-eneciq-ai-platform-to-boost-efficiency-and-knowledge-sharing/"},{"id":"wnn-kepco-2025","label":"WNN · KEPCO and ENEC enhance cooperation (Nov 2025)","url":"https://www.world-nuclear-news.org/articles/kepco-and-enec-enhance-cooperation-in-nuclear-energy"}]'::jsonb, 5)
