insert into kafaa_refusal_policies (id, category, description_en, description_ar, patterns, response_en, response_ar, enabled, stop_conversation) values
('rp-operations', 'operations', 'Plant operations and procedures', 'عمليات المحطة وإجراءاتها', array['how do i operate','emergency operating procedure','تشغيل المفاعل خطوة بخطوة']::text[], 'I can''t help with plant operating procedures. For careers in operations, see the Career Map.', 'لا يمكنني المساعدة في إجراءات تشغيل المحطة. للاطلاع على المهن في العمليات راجع خريطة المهن.', true, false),
('rp-security', 'security', 'Security and physical protection', 'الأمن والحماية المادية', array['security arrangement','physical protection system','perimeter','access control system','drone','الترتيبات الأمنية']::text[], 'I can''t discuss plant security. If you are interested in a security career, the Career Map shows the path and the public requirements.', 'لا يمكنني مناقشة أمن المحطة. إذا كنت مهتماً بمهنة في الأمن، تعرض خريطة المهن المسار والمتطلبات العامة.', true, false),
('rp-safeguards', 'safeguards', 'Safeguards', 'الضمانات', array['nuclear material account','inventory of uranium']::text[], 'Safeguards details are out of scope. The IAEA and FANR publish general information.', 'تفاصيل الضمانات خارج النطاق. تنشر الوكالة والهيئة معلومات عامة.', true, false),
('rp-cyber', 'cyber', 'Cyber details', 'تفاصيل الأمن السيبراني', array['firewall','scada','vulnerability','password']::text[], 'I can''t discuss cyber security details.', 'لا يمكنني مناقشة تفاصيل الأمن السيبراني.', true, false),
('rp-emergency', 'emergency', 'Emergency actions', 'إجراءات الطوارئ', array['evacuat','iodine','emergency zone','what should i do in an emergency','إخلاء']::text[], 'For emergency guidance, use official ENEC and NCEMA pages: Go In, Stay In, Listen In.', 'لإرشادات الطوارئ استخدم صفحات ENEC والهيئة الوطنية الرسمية: ادخل، ابقَ في الداخل، استمع.', true, false),
('rp-medical', 'medical', 'Medical matters', 'المسائل الطبية', array['medical condition','diagnos','my health','fitness for duty test result']::text[], 'I can''t discuss medical matters. Occupational health can help.', 'لا يمكنني مناقشة المسائل الطبية. يمكن للصحة المهنية المساعدة.', true, false),
('rp-exam', 'exam', 'Exam items', 'أسئلة الاختبارات', array['exam question','exam answer','answer key','what is on the fanr exam']::text[], 'I can''t share exam content. Practice quizzes on public topics are available in Learn.', 'لا يمكنني مشاركة محتوى الاختبارات. تتوفر اختبارات تدريبية في موضوعات عامة.', true, false),
('rp-personal', 'personal', 'Other people''s personal data', 'البيانات الشخصية للآخرين', array['name of the operator','phone number of','email of']::text[], 'I can''t share information about other people.', 'لا يمكنني مشاركة معلومات عن أشخاص آخرين.', true, false),
('rp-decision', 'decision', 'Eligibility decisions', 'قرارات الأهلية', array['am i eligible','will i be accepted','will i pass','predict my']::text[], 'I can explain the published criteria, but I can''t decide or predict eligibility, admission or licensing outcomes. ENEC and FANR decide.', 'يمكنني شرح المعايير المنشورة، لكن لا يمكنني تقرير الأهلية أو القبول أو نتائج الترخيص أو توقعها. تقرر ENEC والهيئة ذلك.', true, false),
('rp-concern', 'concern', 'Concerns (stop and show ECP channels)', 'المخاوف (التوقف وعرض القنوات)', array['i want to report','report a concern','harass','retaliat','أريد الإبلاغ','أبلغ عن']::text[], 'I can''t take concerns. Please use the Employee Concerns Program channels: ECP offices, the intranet portal, the 24/7 phone line, email, unit representatives, or FANR''s Report to Protect.', 'لا يمكنني تلقي المخاوف. يرجى استخدام قنوات برنامج مخاوف الموظفين: المكاتب وبوابة الشبكة الداخلية والخط الهاتفي على مدار الساعة والبريد الإلكتروني وممثلي الوحدات أو نظام "أبلغ لتحمي" لدى الهيئة.', true, true),
('rp-injection', 'injection', 'Prompt injection and attempts to change Dalil''s rules', 'محاولات حقن التعليمات أو تغيير قواعد دليل', array['ignore previous instructions','system prompt']::text[], 'I can''t change how I work. I answer only from Kafa''a''s approved sources, with citations.', 'لا يمكنني تغيير طريقة عملي. أجيب فقط من مصادر كفاءة المعتمدة مع ذكر المصدر.', true, false)
