('int-nexus-ledger', 'ENEC NEXUS evidence ledger', 'NEXUS', 'material actions (append)', 'out', '2026-10-08T08:00:00Z', 24, 'ok', 0, 0, 'On event', 'Consequential actions append to nexus_append_ledger, plane PEOPLE.'),
('int-nexus-partner', 'NEXUS partner lens hand-off', 'NEXUS', 'supplier readiness summaries', 'out', '2026-10-01T08:00:00Z', 168, 'ok', 1, 0, 'On event', 'Ready suppliers hand off to /partner/readiness in NEXUS.'),
('int-uaepass', 'UAE Pass (concept)', 'Identity', 'verified identity when a stage needs it', 'in', '2026-10-01T00:00:00Z', 720, 'disabled', 0, 0, 'On demand', 'Not connected in the demo tenant.')
insert into kafaa_feature_flags (id, key, label_en, label_ar, description_en, description_ar, enabled, locked, area, updated_at, updated_by) values
('ff-dalil_public', 'dalil_public', 'Dalil for anonymous visitors', 'دليل للزوار غير المسجلين', 'When off, Dalil asks visitors to sign in before answering. The global kill switch is separate (Dalil settings).', 'عند الإيقاف يطلب دليل من الزوار تسجيل الدخول قبل الإجابة. مفتاح الإيقاف العام منفصل (إعدادات دليل).', true, false, 'dalil', '2026-10-01T08:00:00Z', null),
('ff-dalil_handoff', 'dalil_handoff', 'Dalil human hand-off', 'إحالة دليل إلى شخص', 'Lets users ask for the careers team, a training coordinator or the partner desk, with consent to pass on the conversation.', 'يتيح للمستخدمين طلب فريق المهن أو منسق التدريب أو مكتب الشركاء مع الموافقة على تمرير المحادثة.', true, false, 'dalil', '2026-10-01T08:00:00Z', null),
('ff-contact_form', 'contact_form', 'Public contact form', 'نموذج الاتصال العام', 'When off, the contact page shows official channels only.', 'عند الإيقاف تعرض صفحة الاتصال القنوات الرسمية فقط.', true, false, 'public', '2026-10-01T08:00:00Z', null),
('ff-news', 'news', 'News section on public pages', 'قسم الأخبار في الصفحات العامة', 'Sourced news items on the home page and /news.', 'أخبار موثقة في الصفحة الرئيسية وصفحة الأخبار.', true, false, 'public', '2026-10-01T08:00:00Z', null),
('ff-nexus_links', 'nexus_links', 'Links into ENEC NEXUS', 'روابط إلى ENEC NEXUS', 'Shows deep links into NEXUS Academy, partner readiness and the directory.', 'يعرض روابط مباشرة إلى أكاديمية NEXUS وجاهزية الشركاء والدليل.', true, false, 'nexus', '2026-10-01T08:00:00Z', null),
('ff-self_export', 'self_export', 'Self-service data export', 'تصدير البيانات ذاتياً', 'Lets signed-in users download their own data from My settings.', 'يتيح للمستخدمين تنزيل بياناتهم من "إعداداتي".', true, false, 'privacy', '2026-10-01T08:00:00Z', null),
('ff-speak_up_no_telemetry', 'speak_up_no_telemetry', 'Speak-up: no telemetry (locked)', 'رفع المخاوف: بلا قياس (مقفل)', 'The speak-up route never sends analytics or audit events. Locked on by design.', 'لا يرسل مسار رفع المخاوف أي قياسات أو أحداث تدقيق. مفعّل دائماً بحكم التصميم.', true, true, 'safety', '2026-10-01T08:00:00Z', null),
('ff-gamification_qualification', 'gamification_qualification', 'Points and badges on qualification work (locked off)', 'النقاط والشارات على أعمال التأهيل (مقفل)', 'Qualification is not a game. Locked off by design.', 'التأهيل ليس لعبة. مقفل بحكم التصميم.', false, true, 'safety', '2026-10-01T08:00:00Z', null)
insert into kafaa_skills (id, code, competency_id, name_en, name_ar, area, core, key_level, evidence_keys, adjacent_ids, adv_skill_ids, description_en, description_ar, sources, sort) values
('sk-pf-01', 'PF-01', 'pf-01', 'Reactor theory and nuclear physics fundamentals', 'نظرية المفاعل وأساسيات الفيزياء النووية', 'plant_systems', true, 2, '{}'::text[], array['sk-pf-01-core','sk-pf-01-advfuel','sk-pf-02','sk-pf-02-advcool','sk-pf-03','sk-pf-03-rcs']::text[], '{}'::text[], 'Reactor theory and nuclear physics fundamentals: what a person in a nuclear role needs to know and do, from awareness to expert.', 'نظرية المفاعل وأساسيات الفيزياء النووية: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[]'::jsonb, 0),
('sk-pf-01-core', 'PF-01.1', 'pf-01', 'Core physics and reactivity monitoring', 'فيزياء القلب ومراقبة التفاعلية', 'plant_systems', false, 3, array['qs-sro']::text[], array['sk-pf-01','sk-pf-01-advfuel','sk-pf-02','sk-pf-02-advcool','sk-pf-03','sk-pf-03-rcs']::text[], array['as-reactivity','as-fast-physics']::text[], 'Core physics and reactivity monitoring: part of Reactor theory and nuclear physics fundamentals (PF-01).', 'فيزياء القلب ومراقبة التفاعلية: جزء من نظرية المفاعل وأساسيات الفيزياء النووية (PF-01).', '[]'::jsonb, 1),
('sk-pf-01-advfuel', 'PF-01.2', 'pf-01', 'Advanced fuel forms and core materials', 'أشكال الوقود المتقدمة ومواد القلب', 'plant_systems', false, 2, array['c-adv-smr']::text[], array['sk-pf-01','sk-pf-01-core','sk-pf-02','sk-pf-02-advcool','sk-pf-03','sk-pf-03-rcs']::text[], array['as-triso-fuel','as-graphite','as-salt-materials']::text[], 'Advanced fuel forms and core materials: part of Reactor theory and nuclear physics fundamentals (PF-01).', 'أشكال الوقود المتقدمة ومواد القلب: جزء من نظرية المفاعل وأساسيات الفيزياء النووية (PF-01).', '[]'::jsonb, 2),
('sk-pf-02', 'PF-02', 'pf-02', 'Thermodynamics, heat transfer and fluid flow', 'الديناميكا الحرارية وانتقال الحرارة وجريان الموائع', 'plant_systems', true, 2, '{}'::text[], array['sk-pf-02-advcool','sk-pf-01','sk-pf-01-core','sk-pf-01-advfuel','sk-pf-03','sk-pf-03-rcs']::text[], '{}'::text[], 'Thermodynamics, heat transfer and fluid flow: what a person in a nuclear role needs to know and do, from awareness to expert.', 'الديناميكا الحرارية وانتقال الحرارة وجريان الموائع: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[]'::jsonb, 10),
('sk-pf-02-advcool', 'PF-02.1', 'pf-02', 'Advanced coolant systems (gas, liquid metal, natural circulation)', 'أنظمة التبريد المتقدمة (الغاز والمعادن السائلة والدوران الطبيعي)', 'plant_systems', false, 2, array['c-adv-smr']::text[], array['sk-pf-02','sk-pf-01','sk-pf-01-core','sk-pf-01-advfuel','sk-pf-03','sk-pf-03-rcs']::text[], array['as-gas-coolant','as-liquid-metal','as-passive-safety']::text[], 'Advanced coolant systems (gas, liquid metal, natural circulation): part of Thermodynamics, heat transfer and fluid flow (PF-02).', 'أنظمة التبريد المتقدمة (الغاز والمعادن السائلة والدوران الطبيعي): جزء من الديناميكا الحرارية وانتقال الحرارة وجريان الموائع (PF-02).', '[]'::jsonb, 11),
('sk-pf-03', 'PF-03', 'pf-03', 'APR-1400 integrated plant systems', 'أنظمة محطة APR-1400 المتكاملة', 'plant_systems', true, 2, '{}'::text[], array['sk-pf-03-rcs','sk-pf-03-steam','sk-pf-03-eccs','sk-pf-03-elec','sk-pf-03-aux','sk-pf-03-fuel']::text[], '{}'::text[], 'APR-1400 integrated plant systems: what a person in a nuclear role needs to know and do, from awareness to expert.', 'أنظمة محطة APR-1400 المتكاملة: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[]'::jsonb, 20),
('sk-pf-03-rcs', 'PF-03.1', 'pf-03', 'Reactor coolant system and pressuriser (APR-1400)', 'نظام تبريد المفاعل والمضغاط (APR-1400)', 'plant_systems', false, 3, array['qs-ro','qs-sro','c-coit-sim']::text[], array['sk-pf-03','sk-pf-03-steam','sk-pf-03-eccs','sk-pf-03-elec','sk-pf-03-aux','sk-pf-03-fuel']::text[], array['as-bwr-systems']::text[], 'Reactor coolant system and pressuriser (APR-1400): part of APR-1400 integrated plant systems (PF-03).', 'نظام تبريد المفاعل والمضغاط (APR-1400): جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).', '[]'::jsonb, 21),
('sk-pf-03-steam', 'PF-03.2', 'pf-03', 'Main steam, feedwater and turbine systems', 'أنظمة البخار الرئيسي ومياه التغذية والتوربين', 'plant_systems', false, 3, array['qs-lo-turbine','qs-ro','qs-sro','c-loit-sys']::text[], array['sk-pf-03','sk-pf-03-rcs','sk-pf-03-eccs','sk-pf-03-elec','sk-pf-03-aux','sk-pf-03-fuel']::text[], '{}'::text[], 'Main steam, feedwater and turbine systems: part of APR-1400 integrated plant systems (PF-03).', 'أنظمة البخار الرئيسي ومياه التغذية والتوربين: جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).', '[]'::jsonb, 22),
('sk-pf-03-eccs', 'PF-03.3', 'pf-03', 'Safety injection and emergency core cooling', 'الحقن الآمن والتبريد الطارئ لقلب المفاعل', 'plant_systems', false, 3, array['qs-ro','qs-sro','c-coit-sim','c-sam']::text[], array['sk-pf-03','sk-pf-03-rcs','sk-pf-03-steam','sk-pf-03-elec','sk-pf-03-aux','sk-pf-03-fuel']::text[], '{}'::text[], 'Safety injection and emergency core cooling: part of APR-1400 integrated plant systems (PF-03).', 'الحقن الآمن والتبريد الطارئ لقلب المفاعل: جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).', '[]'::jsonb, 23),
('sk-pf-03-elec', 'PF-03.4', 'pf-03', 'Electrical distribution and emergency diesel generators', 'توزيع الكهرباء ومولدات الديزل للطوارئ', 'plant_systems', false, 2, array['qs-lo-aux','qs-elec','qs-ro']::text[], array['sk-pf-03','sk-pf-03-rcs','sk-pf-03-steam','sk-pf-03-eccs','sk-pf-03-aux','sk-pf-03-fuel']::text[], '{}'::text[], 'Electrical distribution and emergency diesel generators: part of APR-1400 integrated plant systems (PF-03).', 'توزيع الكهرباء ومولدات الديزل للطوارئ: جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).', '[]'::jsonb, 24),
('sk-pf-03-aux', 'PF-03.5', 'pf-03', 'Auxiliary systems (chemical and volume control, component cooling, HVAC)', 'الأنظمة المساعدة (التحكم الكيميائي والحجمي وتبريد المكونات والتهوية)', 'plant_systems', false, 2, array['qs-lo-aux','c-loit-sys']::text[], array['sk-pf-03','sk-pf-03-rcs','sk-pf-03-steam','sk-pf-03-eccs','sk-pf-03-elec','sk-pf-03-fuel']::text[], '{}'::text[], 'Auxiliary systems (chemical and volume control, component cooling, HVAC): part of APR-1400 integrated plant systems (PF-03).', 'الأنظمة المساعدة (التحكم الكيميائي والحجمي وتبريد المكونات والتهوية): جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).', '[]'::jsonb, 25),
('sk-pf-03-fuel', 'PF-03.6', 'pf-03', 'Fuel handling and refuelling', 'مناولة الوقود وإعادة التزود به', 'plant_systems', false, 2, array['qs-sro','c-apr']::text[], array['sk-pf-03','sk-pf-03-rcs','sk-pf-03-steam','sk-pf-03-eccs','sk-pf-03-elec','sk-pf-03-aux']::text[], '{}'::text[], 'Fuel handling and refuelling: part of APR-1400 integrated plant systems (PF-03).', 'مناولة الوقود وإعادة التزود به: جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).', '[]'::jsonb, 26),
('sk-co-01', 'CO-01', 'co-01', 'Procedure use and adherence', 'استخدام الإجراءات والالتزام بها', 'operations', true, 2, '{}'::text[], array['sk-co-01-eop','sk-co-01-rounds','sk-co-02','sk-co-03','sk-co-03-startup']::text[], '{}'::text[], 'Procedure use and adherence: what a person in a nuclear role needs to know and do, from awareness to expert.', 'استخدام الإجراءات والالتزام بها: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[]'::jsonb, 30),
