insert into kafaa_opportunities (id, posted_by, org_id, family_id, host_role_id, host_team, kind, title_en, title_ar, summary_en, summary_ar, skills_needed, skills_gained, hours_week, start_on, end_on, seats, seats_taken, location_type, eligible_families, priority_flags, status, listed, created_at, updated_at) values
('opp-u3-outage-valve-walkdowns', 'p-outage-manager', 'enec-ops', 'outage', 'outage-manager-planner', null, 'outage_support', 'Unit 3 refuelling outage: work-package walkdown support', 'انقطاع إعادة التزوّد بالوقود للوحدة 3: دعم جولات التحقق من حزم العمل', 'Support the outage control centre by checking work packages and walkdown readiness before each outage window. You work beside experienced outage planners, including KHNP colleagues, and learn how a refuelling outage is sequenced and controlled.', 'ادعم مركز التحكم في الانقطاع بمراجعة حزم العمل وجاهزية الجولات قبل كل نافذة انقطاع. ستعمل إلى جانب مخططي انقطاع ذوي خبرة، منهم زملاء من KHNP، وتتعلم كيف يُرتّب انقطاع إعادة التزوّد بالوقود ويُدار.', array['sk-co-01-rounds','sk-hu-01-star']::text[], array['sk-mp-01-outage','sk-hu-02-brief']::text[], 12, '2026-11-02', '2026-12-18', 3, 0, 'site_non_protected', '{}'::text[], array['knowledge_transfer']::text[], 'open', true, '2026-10-04T07:00:00Z', '2026-10-04T07:00:00Z'),
('opp-outage-schedule-analytics', 'p-outage-manager', 'enec-ops', 'outage', 'outage-manager-planner', null, 'project', 'Outage schedule analytics: critical-path dashboard', 'تحليلات جدول الانقطاع: لوحة المسار الحرج', 'Build a simple dashboard that tracks critical-path activities and schedule slippage across the last three outages, using exported schedule data only. The result feeds the lessons-learned review for the next outage.', 'أنشئ لوحة بسيطة تتابع أنشطة المسار الحرج وانزلاق الجدول في آخر ثلاثة انقطاعات، باستخدام بيانات الجدول المصدّرة فقط. تُستخدم النتيجة في مراجعة الدروس المستفادة للانقطاع القادم.', array['sk-da-01']::text[], array['sk-mp-01-outage','sk-da-01-analysis']::text[], 6, '2026-10-26', '2027-01-29', 1, 0, 'office', '{}'::text[], array['emirati_development']::text[], 'open', true, '2026-10-02T07:00:00Z', '2026-10-02T07:00:00Z'),
('opp-sim-scenario-pilot', 'p-training-mgr', 'enec-ops', 'training', 'nuclear-training-instructor', 'training', 'project', 'Simulator training scenario pilot with the instructor team', 'تجربة سيناريوهات تدريب على المحاكي مع فريق المدربين', 'Help instructors dry-run new transient training scenarios on the full-scope simulator before they enter the continuing-training programme. You give the operator view on realism and timing; no exam content is involved.', 'ساعد المدربين في التجربة الأولية لسيناريوهات تدريب جديدة على العوابر في المحاكي الكامل قبل إدخالها في برنامج التدريب المستمر. تقدّم منظور المشغّل حول الواقعية والتوقيت، ولا يتضمن ذلك أي محتوى امتحاني.', array['sk-co-01-eop','sk-pf-03-rcs']::text[], array['sk-ld-01-instruct','sk-co-01-eop']::text[], 8, '2026-11-01', '2027-02-26', 2, 0, 'office', array['operations','training']::text[], array['knowledge_transfer']::text[], 'open', true, '2026-09-30T07:00:00Z', '2026-09-30T07:00:00Z'),
('opp-instructor-shadow-coct', 'p-training-mgr', 'enec-ops', 'training', 'nuclear-training-instructor', 'training', 'shadowing', 'Shadow a continuing-training instructor for one COCT week', 'مرافقة مدرب تدريب مستمر لأسبوع واحد من التدريب المستمر للمشغّلين', 'Spend a continuing-training week with an instructor: lesson preparation, simulator debriefs and feedback to crews. A first step for anyone considering the instructor path.', 'اقضِ أسبوع تدريب مستمر مع أحد المدربين: تحضير الدروس، وجلسات المراجعة بعد المحاكي، وتقديم الملاحظات للأطقم. خطوة أولى لكل من يفكر في مسار التدريب.', array['sk-co-01']::text[], array['sk-ld-01-instruct','sk-ld-01-coach']::text[], 10, '2026-11-09', '2026-12-04', 2, 0, 'office', '{}'::text[], array['new_joiner_friendly']::text[], 'open', true, '2026-09-28T07:00:00Z', '2026-09-28T07:00:00Z'),
('opp-rp-dose-desk', 'p-rp-lead', 'enec-ops', 'radiation-protection', 'radiation-protection-technician', null, 'shadowing', 'Radiation protection: dose assessment desk rotation', 'الوقاية من الإشعاع: تناوب على مكتب تقييم الجرعات', 'Join the dosimetry desk for four weeks and learn how planned dose is estimated for work packages and compared with actual dose afterwards. Office-based work with anonymised dose records.', 'انضم إلى مكتب قياس الجرعات لمدة أربعة أسابيع وتعلّم كيف تُقدّر الجرعة المخططة لحزم العمل وتُقارن بالجرعة الفعلية بعد ذلك. عمل مكتبي على سجلات جرعات مجهّلة الهوية.', array['sk-rp-01']::text[], array['sk-rp-01-dose','sk-rp-02']::text[], 8, '2026-11-16', '2026-12-11', 2, 0, 'office', array['radiation-protection','chemistry','operations','maintenance']::text[], '{}'::text[], 'open', true, '2026-09-26T07:00:00Z', '2026-09-26T07:00:00Z'),
('opp-chem-lab-qa-review', 'p-chem-sup', 'enec-ops', 'chemistry', 'chemistry-technician', null, 'project', 'Chemistry laboratory QA procedure review', 'مراجعة إجراءات ضمان الجودة في مختبر الكيمياء', 'Review the laboratory quality-control procedures against the current instrument fleet and propose clearer acceptance criteria. Supervised by the chemistry supervisor and a quality engineer.', 'راجع إجراءات ضبط الجودة في المختبر مقارنةً بالأجهزة الحالية واقترح معايير قبول أوضح. تحت إشراف مشرف الكيمياء ومهندس جودة.', array['sk-ch-02']::text[], array['sk-ch-02-labqa','sk-qa-02']::text[], 6, '2026-10-19', '2026-12-31', 1, 0, 'office', '{}'::text[], '{}'::text[], 'open', true, '2026-09-24T07:00:00Z', '2026-09-24T07:00:00Z'),
('opp-ep-exercise-evaluator', 'p-ep-manager', 'enec-ops', 'emergency-preparedness', 'emergency-preparedness-coordinator', null, 'project', 'Emergency exercise controller and evaluator support', 'دعم التحكم والتقييم في تمارين الطوارئ', 'Act as a controller or evaluator for the year-end emergency preparedness exercise at the emergency facilities. You observe decision-making, record timings and contribute to the after-action report.', 'شارك بصفة متحكّم أو مقيّم في تمرين التأهب للطوارئ في نهاية العام في مرافق الطوارئ. ستلاحظ اتخاذ القرار وتسجّل التوقيتات وتساهم في تقرير ما بعد التمرين.', array['sk-ep-01']::text[], array['sk-ep-01-ero','sk-ld-02-decide']::text[], 4, '2026-11-23', '2026-12-18', 4, 0, 'site_non_protected', '{}'::text[], '{}'::text[], 'open', true, '2026-09-22T07:00:00Z', '2026-09-22T07:00:00Z'),
('opp-oe-review-2026-q4', 'p-cap-chair', 'enec-ops', 'oversight', 'nuclear-oversight-npi', null, 'oe_review', 'Operating experience review: industry events, third quarter 2026', 'مراجعة الخبرة التشغيلية: أحداث القطاع في الربع الثالث 2026', 'Screen published industry operating-experience reports for lessons that apply to Barakah, and draft applicability reviews for the corrective action programme. Builds judgement on human performance and safety culture.', 'افحص تقارير الخبرة التشغيلية المنشورة في القطاع بحثاً عن دروس تنطبق على براكة، وأعدّ مسودات مراجعات الانطباق لبرنامج الإجراءات التصحيحية. تبني الحكم في الأداء البشري وثقافة السلامة.', array['sk-hu-01']::text[], array['sk-hu-02-brief','sk-sc-02','sk-ns-01']::text[], 4, '2026-10-20', '2026-12-15', 3, 1, 'office', '{}'::text[], '{}'::text[], 'open', true, '2026-09-20T07:00:00Z', '2026-09-20T07:00:00Z'),
('opp-knowledge-capture-senior-ops', 'p-ops-ceo', 'enec-ops', 'operations', null, null, 'knowledge_capture', 'Knowledge capture: structured interviews with departing senior operators', 'التقاط المعرفة: مقابلات منظمة مع كبار المشغّلين المغادرين', 'Prepare and run structured interviews with senior operators and KHNP experts before they leave, then turn them into searchable notes. Part of the handover to the next generation of Emirati operators before 2030.', 'حضّر وأجرِ مقابلات منظمة مع كبار المشغّلين وخبراء KHNP قبل مغادرتهم، ثم حوّلها إلى ملاحظات قابلة للبحث. جزء من التسليم للجيل القادم من المشغّلين المواطنين قبل عام 2030.', array['sk-co-01']::text[], array['sk-hu-02-brief','sk-ld-01-coach']::text[], 4, '2026-11-02', '2027-03-31', 3, 1, 'office', '{}'::text[], array['knowledge_transfer','emirati_development']::text[], 'open', true, '2026-09-18T07:00:00Z', '2026-09-18T07:00:00Z'),
('opp-stem-outreach-schools', 'p-training-mgr', 'enec-ops', 'training', 'nuclear-training-instructor', 'training', 'outreach', 'STEM outreach: careers talks for secondary schools', 'التواصل في مجالات العلوم والتقنية: محاضرات مهنية لطلاب المدارس الثانوية', 'Visit secondary schools in Al Dhafra and Abu Dhabi with the talent team to explain careers in nuclear energy. Training on presenting and safeguarding is provided before the first visit.', 'زر المدارس الثانوية في الظفرة وأبوظبي مع فريق المواهب لشرح المسارات المهنية في الطاقة النووية. يُقدَّم تدريب على العرض وحماية الطلاب قبل الزيارة الأولى.', '{}'::text[], array['sk-ld-01-coach','sk-sc-01']::text[], 3, '2026-11-10', '2027-03-31', 6, 1, 'office', '{}'::text[], array['emirati_development','new_joiner_friendly']::text[], 'open', true, '2026-10-04T07:00:00Z', '2026-10-04T07:00:00Z'),
('opp-digital-twin-study', 'p-ops-ceo', 'enec-ops', 'operations', null, null, 'research', 'Research: digital twin feasibility for condensate system trending', 'بحث: جدوى التوأم الرقمي لتحليل اتجاهات نظام المكثّفات', 'Work with a university research partner on a feasibility study for a digital twin of the condensate system, using historical, exported performance data only. No connection to plant systems.', 'اعمل مع شريك بحثي جامعي على دراسة جدوى لتوأم رقمي لنظام المكثّفات باستخدام بيانات أداء تاريخية مصدّرة فقط. لا يوجد أي اتصال بأنظمة المحطة.', array['sk-da-01','sk-en-02']::text[], array['sk-da-01-twins','sk-en-02-perf']::text[], 6, '2026-12-01', '2027-05-28', 2, 0, 'office', '{}'::text[], array['emirati_development']::text[], 'open', true, '2026-10-02T07:00:00Z', '2026-10-02T07:00:00Z'),
('opp-governed-ai-pilot', 'p-work-control', 'enec-ops', 'operations', 'operations-support-work-control', 'ops-wc', 'project', 'Governed AI pilot: reviewing AI-drafted work-order summaries', 'تجربة الذكاء الاصطناعي المحوكم: مراجعة ملخصات أوامر العمل المُعدّة آلياً', 'Review AI-drafted summaries of closed work orders against the source records, log every error and help write the review checklist. Human review stays mandatory; nothing is used for decisions.', 'راجع ملخصات أوامر العمل المغلقة التي أعدّها الذكاء الاصطناعي مقارنةً بالسجلات الأصلية، وسجّل كل خطأ، وساعد في كتابة قائمة المراجعة. تبقى المراجعة البشرية إلزامية ولا يُستخدم أي شيء لاتخاذ القرار.', array['sk-da-02']::text[], array['sk-da-02-review','sk-da-01-analysis']::text[], 4, '2026-11-01', '2027-01-29', 2, 0, 'office', '{}'::text[], '{}'::text[], 'open', true, '2026-09-30T07:00:00Z', '2026-09-30T07:00:00Z'),
('opp-work-planning-shadow', 'p-work-control', 'enec-ops', 'operations', 'operations-support-work-control', 'ops-wc', 'shadowing', 'Shadow the work planning team for four weeks', 'مرافقة فريق تخطيط الأعمال لمدة أربعة أسابيع', 'See how maintenance work is screened against technical specifications, scheduled and released. Ideal for operators and technicians who want to understand the planning side.', 'تعرّف على كيفية فحص أعمال الصيانة مقابل المواصفات الفنية وجدولتها وإطلاقها. مناسب للمشغّلين والفنيين الراغبين في فهم جانب التخطيط.', array['sk-hu-01']::text[], array['sk-ns-02-techspec','sk-mp-01-outage']::text[], 10, '2026-11-02', '2026-11-27', 2, 0, 'office', '{}'::text[], array['new_joiner_friendly']::text[], 'open', true, '2026-09-28T07:00:00Z', '2026-09-28T07:00:00Z'),
('opp-licensing-psr-inputs', 'p-dra', 'enec-ops', 'licensing', 'regulatory-affairs-licensing-engineer', null, 'project', 'Licensing support: periodic safety review inputs', 'دعم الترخيص: مدخلات المراجعة الدورية للسلامة', 'Collect and check the operating-experience inputs for a periodic safety review chapter with the regulatory affairs team. Kafa''a records the development; regulatory submissions remain with the licensee.', 'اجمع وتحقّق من مدخلات الخبرة التشغيلية لفصل من المراجعة الدورية للسلامة مع فريق الشؤون التنظيمية. تسجّل كفاءة التطوير فقط، وتبقى التقديمات التنظيمية مسؤولية المرخَّص له.', array['sk-ns-02']::text[], array['sk-ns-02-licensing']::text[], 6, '2026-10-26', '2027-01-15', 1, 0, 'office', array['licensing','engineering','operations','oversight']::text[], '{}'::text[], 'open', true, '2026-09-26T07:00:00Z', '2026-09-26T07:00:00Z'),
('opp-supplier-quality-surveillance', 'p-head-sq', 'enec', 'quality', 'quality-assurance-qc', null, 'shadowing', 'Supplier quality surveillance and commercial-grade dedication', 'الرقابة على جودة الموردين واعتماد المكونات التجارية', 'Shadow quality engineers through a supplier surveillance plan and a commercial-grade dedication package, from document review to the acceptance decision.', 'رافق مهندسي الجودة خلال خطة رقابة على أحد الموردين وحزمة اعتماد لمكونات تجارية، من مراجعة الوثائق حتى قرار القبول.', array['sk-qa-01']::text[], array['sk-qa-01-inspect','sk-qa-02-cgd']::text[], 6, '2026-11-16', '2026-12-11', 2, 0, 'office', '{}'::text[], '{}'::text[], 'open', true, '2026-09-24T07:00:00Z', '2026-09-24T07:00:00Z'),
('opp-icv-supplier-mapping', 'p-cpo', 'enec', 'supply-chain', null, null, 'project', 'In-country value: local supplier capability mapping', 'القيمة المحلية المضافة: رسم خريطة قدرات الموردين المحليين', 'Map local suppliers against upcoming spare-parts and services needs and summarise capability gaps for the supply chain team. Uses public and partner-provided information only.', 'اربط الموردين المحليين بالاحتياجات القادمة من قطع الغيار والخدمات، ولخّص فجوات القدرات لفريق سلسلة الإمداد. باستخدام المعلومات العامة وتلك المقدمة من الشركاء فقط.', '{}'::text[], array['sk-en-01-project','sk-qa-02']::text[], 5, '2026-11-02', '2027-02-26', 1, 0, 'office', '{}'::text[], array['emirati_development']::text[], 'open', true, '2026-09-22T07:00:00Z', '2026-09-22T07:00:00Z'),
('opp-crewb-procedure-usability', 'p-sro', 'enec-ops', 'operations', 'shift-supervisor', 'ops-crew-b', 'project', 'Crew B: abnormal operating procedure usability review', 'الطاقم ب: مراجعة سهولة استخدام إجراءات التشغيل غير الاعتيادية', 'Walk through selected abnormal operating procedures on the simulator and record usability issues for the procedure owners. Draft: dates to be confirmed with the training schedule.', 'استعرض إجراءات تشغيل غير اعتيادية مختارة على المحاكي وسجّل مشكلات سهولة الاستخدام لمالكي الإجراءات. مسودة: تُؤكَّد التواريخ مع جدول التدريب.', array['sk-co-01-eop']::text[], array['sk-co-03','sk-hu-02-brief']::text[], 4, '2026-11-16', '2027-01-15', 2, 0, 'office', array['operations']::text[], '{}'::text[], 'draft', false, '2026-09-20T07:00:00Z', '2026-09-20T07:00:00Z'),
('opp-crewb-turnover-capture', 'p-sro', 'enec-ops', 'operations', 'shift-supervisor', 'ops-crew-b', 'knowledge_capture', 'Crew B: capture shift-turnover good practice', 'الطاقم ب: توثيق الممارسات الجيدة في تسليم الوردية', 'Observe shift turnovers, interview senior operators about what makes a good turnover and write a short guide for new operators.', 'لاحظ عمليات تسليم الوردية، وقابل كبار المشغّلين حول ما يجعل التسليم جيداً، واكتب دليلاً قصيراً للمشغّلين الجدد.', array['sk-co-01']::text[], array['sk-ld-01-coach','sk-co-03']::text[], 3, '2026-10-19', '2027-01-29', 2, 0, 'office', array['operations']::text[], array['knowledge_transfer']::text[], 'open', true, '2026-09-18T07:00:00Z', '2026-09-18T07:00:00Z'),
('opp-fire-drill-reviews', 'p-emergency-director', 'enec-ops', 'emergency-preparedness', null, null, 'oe_review', 'Fire drill after-action reviews', 'مراجعات ما بعد تمارين الحريق', 'Review the last year of fire drill reports, identify repeat findings and propose two improvements for the fire brigade training plan.', 'راجع تقارير تمارين الحريق للعام الماضي، وحدّد الملاحظات المتكررة، واقترح تحسينين لخطة تدريب فرقة الإطفاء.', array['sk-ep-02']::text[], array['sk-ep-02-fire','sk-hu-02-brief']::text[], 3, '2026-11-02', '2026-12-18', 2, 0, 'office', '{}'::text[], '{}'::text[], 'open', true, '2026-10-04T07:00:00Z', '2026-10-04T07:00:00Z'),
('opp-u2-outage-2026-support', 'p-outage-manager', 'enec-ops', 'outage', 'outage-manager-planner', null, 'outage_support', 'Unit 2 outage 2026: outage control centre support', 'انقطاع الوحدة 2 لعام 2026: دعم مركز التحكم في الانقطاع', 'Support the outage control centre during the Unit 2 refuelling outage: work-package tracking, walkdown readiness and daily schedule updates.', 'دعم مركز التحكم في الانقطاع خلال انقطاع إعادة التزوّد بالوقود للوحدة 2: متابعة حزم العمل وجاهزية الجولات والتحديثات اليومية للجدول.', array['sk-co-01-rounds']::text[], array['sk-mp-01-outage','sk-hu-02-brief']::text[], 12, '2026-04-06', '2026-05-29', 4, 4, 'site_non_protected', '{}'::text[], array['knowledge_transfer']::text[], 'closed', true, '2026-03-07T07:00:00Z', '2026-03-07T07:00:00Z'),
('opp-oe-review-2026-q2', 'p-cap-chair', 'enec-ops', 'oversight', 'nuclear-oversight-npi', null, 'oe_review', 'Operating experience review: industry events, first half 2026', 'مراجعة الخبرة التشغيلية: أحداث القطاع في النصف الأول من 2026', 'Screen published industry operating-experience reports from the first half of 2026 and draft applicability reviews for the corrective action programme.', 'افحص تقارير الخبرة التشغيلية المنشورة في القطاع للنصف الأول من 2026، وأعدّ مسودات مراجعات الانطباق لبرنامج الإجراءات التصحيحية.', array['sk-hu-01']::text[], array['sk-hu-02-brief','sk-sc-02']::text[], 4, '2026-06-01', '2026-07-31', 3, 3, 'office', '{}'::text[], '{}'::text[], 'closed', true, '2026-05-02T07:00:00Z', '2026-05-02T07:00:00Z'),
('opp-sim-instructor-assist-2026', 'p-training-mgr', 'enec-ops', 'training', 'nuclear-training-instructor', 'training', 'shadowing', 'Simulator instructor assistant, spring 2026', 'مساعد مدرب المحاكي، ربيع 2026', 'Assist simulator instructors during the spring continuing-training cycle: scenario set-up, timing logs and crew debriefs.', 'مساعدة مدربي المحاكي خلال دورة التدريب المستمر في الربيع: إعداد السيناريوهات وسجلات التوقيت وجلسات المراجعة مع الأطقم.', array['sk-co-01']::text[], array['sk-ld-01-instruct','sk-ld-01-coach']::text[], 8, '2026-05-04', '2026-06-26', 2, 2, 'office', '{}'::text[], '{}'::text[], 'filled', true, '2026-04-04T07:00:00Z', '2026-04-04T07:00:00Z'),
('opp-chem-trending-2026', 'p-chem-sup', 'enec-ops', 'chemistry', 'chemistry-technician', null, 'project', 'Primary chemistry trending workbook', 'مصنّف تحليل اتجاهات الكيمياء في الدائرة الأولية', 'Build a trending workbook for primary-side chemistry parameters from exported laboratory results and present the first quarterly review.', 'أنشئ مصنّفاً لتحليل اتجاهات معاملات الكيمياء في الدائرة الأولية من نتائج المختبر المصدّرة، وقدّم أول مراجعة ربع سنوية.', array['sk-ch-01']::text[], array['sk-ch-01-primary','sk-da-01-analysis']::text[], 4, '2026-03-02', '2026-06-30', 1, 1, 'office', '{}'::text[], '{}'::text[], 'closed', true, '2026-01-31T07:00:00Z', '2026-01-31T07:00:00Z'),
('opp-careers-fair-2026', 'p-training-mgr', 'enec-ops', 'training', 'nuclear-training-instructor', 'training', 'outreach', 'University careers fairs, autumn 2026', 'معارض التوظيف الجامعية، خريف 2026', 'Represent nuclear careers at university careers fairs with the talent team and answer students'' questions about operator and engineering pathways.', 'مثّل المسارات المهنية النووية في معارض التوظيف الجامعية مع فريق المواهب، وأجب عن أسئلة الطلاب حول مسارات التشغيل والهندسة.', '{}'::text[], array['sk-ld-01-coach','sk-sc-01']::text[], 2, '2026-09-01', '2026-10-31', 5, 5, 'office', '{}'::text[], array['emirati_development']::text[], 'filled', true, '2026-08-02T07:00:00Z', '2026-08-02T07:00:00Z'),
('opp-rp-dose-trend-2026', 'p-rp-lead', 'enec-ops', 'radiation-protection', 'radiation-protection-technician', null, 'research', 'Research: collective dose trends across outages', 'بحث: اتجاهات الجرعة الجماعية عبر الانقطاعات', 'Analyse anonymised collective dose data across outages and compare with published industry benchmarks.', 'حلّل بيانات الجرعة الجماعية المجهّلة عبر الانقطاعات وقارنها بالمعايير المرجعية المنشورة في القطاع.', array['sk-rp-01']::text[], array['sk-rp-01-dose','sk-da-01-analysis']::text[], 4, '2026-08-03', '2026-12-18', 1, 1, 'office', '{}'::text[], '{}'::text[], 'filled', true, '2026-07-04T07:00:00Z', '2026-07-04T07:00:00Z')
