insert into kafaa_rotation_templates (id, programme, owner_id, title_en, title_ar, summary_en, summary_ar, duration_min_months, duration_max_months, steps, eligible_families, sources, status, listed, created_at, updated_at) values
('rt-gdp-engineering', 'gdp', 'p-chco', 'Graduate Development Programme: engineering and plant support rotation', 'برنامج تطوير الخريجين: تناوب الهندسة ودعم المحطة', 'Position-targeted, workplace-based development for graduate engineers: four six-month placements across plant engineering, outage and work management, supplier quality and licensing, each with skill objectives signed off by the host. ENEC describes the GDP as 18 to 36 months.', 'تطوير موجّه نحو الوظيفة وقائم على بيئة العمل للمهندسين الخريجين: أربعة تناوبات مدة كل منها ستة أشهر في هندسة المحطة، وإدارة الانقطاعات والأعمال، وجودة الموردين، والترخيص، ولكل تناوب أهداف مهارية يعتمدها المضيف. تصف المؤسسة البرنامج بأنه يمتد من 18 إلى 36 شهراً.', 18, 36, '[{"seq":1,"family_id":"engineering","host_team_en":"Plant engineering: systems and modifications","host_team_ar":"هندسة المحطة: الأنظمة والتعديلات","host_role_id":"systems-design-plant-engineer","host_manager_id":"p-ops-ceo","host_name_en":"CEO, ENEC Operations (role card)","host_name_ar":"الرئيس التنفيذي لـENEC للعمليات (بطاقة دور)","months":6,"site_induction":true,"objectives":[{"id":"o1-1","skill_id":"sk-en-01-mods","level":2,"text_en":"Prepare a minor design-change package with a reviewer","text_ar":"إعداد حزمة تعديل تصميمي بسيط مع مراجِع"},{"id":"o1-2","skill_id":"sk-en-02","level":2,"text_en":"Trend one system health indicator and present it","text_ar":"متابعة اتجاه مؤشر واحد لصحة نظام وعرضه"},{"id":"o1-3","skill_id":"sk-pf-03","level":1,"text_en":"Walk down the main primary and secondary systems","text_ar":"القيام بجولة على الأنظمة الرئيسية في الدائرتين الأولية والثانوية"}]},{"seq":2,"family_id":"outage","host_team_en":"Outage and work management","host_team_ar":"إدارة الانقطاعات والأعمال","host_role_id":"outage-manager-planner","host_manager_id":"p-outage-manager","host_name_en":"Outage Manager (role card)","host_name_ar":"مدير فترات الإيقاف (بطاقة دور)","months":6,"site_induction":true,"objectives":[{"id":"o2-1","skill_id":"sk-mp-01-outage","level":2,"text_en":"Track work packages through one outage window","text_ar":"متابعة حزم العمل خلال نافذة انقطاع واحدة"},{"id":"o2-2","skill_id":"sk-hu-02-brief","level":2,"text_en":"Run pre-job briefs with a supervisor present","text_ar":"إدارة إحاطات ما قبل العمل بحضور مشرف"},{"id":"o2-3","skill_id":"sk-en-01-project","level":1,"text_en":"Keep the schedule-variance log for a project","text_ar":"إدارة سجل انحراف الجدول لمشروع"}]},{"seq":3,"family_id":"quality","host_team_en":"Supplier quality and inspection","host_team_ar":"جودة الموردين والفحص","host_role_id":"quality-assurance-qc","host_manager_id":"p-head-sq","host_name_en":"Head of Supplier Quality (role card)","host_name_ar":"رئيس جودة الموردين (بطاقة دور)","months":6,"site_induction":false,"objectives":[{"id":"o3-1","skill_id":"sk-qa-01-inspect","level":2,"text_en":"Perform receiving inspections under supervision","text_ar":"إجراء فحوصات الاستلام تحت الإشراف"},{"id":"o3-2","skill_id":"sk-qa-02","level":2,"text_en":"Review a supplier quality plan against requirements","text_ar":"مراجعة خطة جودة لمورد مقابل المتطلبات"},{"id":"o3-3","skill_id":"sk-qa-02-cgd","level":1,"text_en":"Follow one commercial-grade dedication package end to end","text_ar":"متابعة حزمة اعتماد لمكوّن تجاري من البداية إلى النهاية"}]},{"seq":4,"family_id":"licensing","host_team_en":"Regulatory affairs and licensing","host_team_ar":"الشؤون التنظيمية والترخيص","host_role_id":"regulatory-affairs-licensing-engineer","host_manager_id":"p-dra","host_name_en":"Director Regulatory Affairs (role card)","host_name_ar":"مدير الشؤون التنظيمية (بطاقة دور)","months":6,"site_induction":false,"objectives":[{"id":"o4-1","skill_id":"sk-ns-02-licensing","level":2,"text_en":"Draft an applicability review for a licensing commitment","text_ar":"إعداد مسودة مراجعة انطباق لالتزام ترخيصي"},{"id":"o4-2","skill_id":"sk-ns-02-techspec","level":1,"text_en":"Trace a technical specification to its basis","text_ar":"تتبّع مواصفة فنية حتى أساسها"},{"id":"o4-3","skill_id":"sk-ns-01","level":1,"text_en":"Summarise one safety-analysis chapter for a briefing","text_ar":"تلخيص فصل من تحليل السلامة لإحاطة"}]}]'::jsonb, '{}'::text[], '[{"id":"enec-careers","label":"ENEC · Careers","url":"https://www.enec.ae/careers-and-scholarships/careers/"},{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"}]'::jsonb, 'active', true, '2025-06-01T09:00:00Z', '2026-09-15T09:00:00Z'),
('rt-gpo-field', 'gpo', 'p-training-mgr', 'Graduate Plant Operator: first two years in the field and on the simulator', 'مشغّل المحطة الخريج: السنتان الأوليان في الميدان وعلى المحاكي', 'GPO graduates start as Local Operators. This rotation builds field rounds, chemistry and radiation-protection awareness, simulator procedure use and work-control understanding before SRO training, which ENEC describes as starting after three years.', 'يبدأ خريجو البرنامج كمشغّلين محليين. يبني هذا التناوب مهارات الجولات الميدانية، والوعي بالكيمياء والوقاية من الإشعاع، واستخدام الإجراءات على المحاكي، وفهم مراقبة الأعمال، قبل تدريب كبير مشغّلي المفاعل الذي تذكر المؤسسة أنه يبدأ بعد ثلاث سنوات.', 24, 36, '[{"seq":1,"family_id":"operations","host_team_en":"Field operations, Crew B","host_team_ar":"العمليات الميدانية، الطاقم ب","host_role_id":"local-operator","host_manager_id":"p-sro","host_name_en":"Shift Manager · licensed SRO, Crew B (role card)","host_name_ar":"مدير الوردية · مشغّل أول مرخّص، الطاقم ب (بطاقة دور)","months":9,"site_induction":true,"objectives":[{"id":"o1-1","skill_id":"sk-co-01-rounds","level":2,"text_en":"Complete operator rounds on two systems unaided","text_ar":"إكمال جولات المشغّل على نظامين دون مساعدة"},{"id":"o1-2","skill_id":"sk-hu-01-star","level":2,"text_en":"Use self-checking (STAR) on every manipulation","text_ar":"استخدام التحقق الذاتي (STAR) في كل عملية تشغيل"},{"id":"o1-3","skill_id":"sk-pf-03","level":1,"text_en":"Explain the flow path of the main steam and feedwater systems","text_ar":"شرح مسار التدفق في نظامي البخار الرئيسي ومياه التغذية"}]},{"seq":2,"family_id":"chemistry","host_team_en":"Chemistry and radiation protection exposure","host_team_ar":"التعرّف على الكيمياء والوقاية من الإشعاع","host_role_id":"chemistry-technician","host_manager_id":"p-chem-sup","host_name_en":"Chemistry Supervisor (role card)","host_name_ar":"مشرف الكيمياء (بطاقة دور)","months":3,"site_induction":true,"objectives":[{"id":"o2-1","skill_id":"sk-ch-01-primary","level":1,"text_en":"Observe primary-chemistry sampling and the results review","text_ar":"ملاحظة أخذ عينات كيمياء الدائرة الأولية ومراجعة النتائج"},{"id":"o2-2","skill_id":"sk-rp-01","level":1,"text_en":"Explain dose limits and the work permit dose estimate","text_ar":"شرح حدود الجرعة وتقدير الجرعة في تصريح العمل"},{"id":"o2-3","skill_id":"sk-rp-02-survey","level":1,"text_en":"Accompany a radiation survey and read the survey map","text_ar":"مرافقة مسح إشعاعي وقراءة خريطة المسح"}]},{"seq":3,"family_id":"training","host_team_en":"Simulator and procedures","host_team_ar":"المحاكي والإجراءات","host_role_id":"nuclear-training-instructor","host_manager_id":"p-training-mgr","host_name_en":"Training Manager (role card)","host_name_ar":"مدير التدريب (بطاقة دور)","months":6,"site_induction":false,"objectives":[{"id":"o3-1","skill_id":"sk-co-01-eop","level":2,"text_en":"Follow emergency operating procedures in simulator sessions","text_ar":"اتباع إجراءات التشغيل الطارئة في جلسات المحاكي"},{"id":"o3-2","skill_id":"sk-pf-03-rcs","level":2,"text_en":"Describe reactor coolant system responses to transients","text_ar":"وصف استجابات نظام تبريد المفاعل للعوابر"},{"id":"o3-3","skill_id":"sk-hu-02-brief","level":1,"text_en":"Take part in crew briefs and debriefs","text_ar":"المشاركة في إحاطات الطاقم وجلسات المراجعة"}]},{"seq":4,"family_id":"operations","host_team_en":"Work control and outage planning","host_team_ar":"مراقبة الأعمال وتخطيط الانقطاع","host_role_id":"operations-support-work-control","host_manager_id":"p-work-control","host_name_en":"Execution Supervisor · Work Control (role card)","host_name_ar":"مشرف التنفيذ · التحكم في الأعمال (بطاقة دور)","months":6,"site_induction":true,"objectives":[{"id":"o4-1","skill_id":"sk-ns-02-techspec","level":1,"text_en":"Screen work orders against technical specifications","text_ar":"فحص أوامر العمل مقابل المواصفات الفنية"},{"id":"o4-2","skill_id":"sk-mp-01-outage","level":1,"text_en":"Support one outage window from the work control centre","text_ar":"دعم نافذة انقطاع واحدة من مركز مراقبة الأعمال"},{"id":"o4-3","skill_id":"sk-co-03","level":1,"text_en":"Prepare equipment clearances with a reviewer","text_ar":"إعداد عزل المعدات مع مراجِع"}]}]'::jsonb, array['operations']::text[], '[{"id":"enec-gpo","label":"ENEC · Graduate Plant Operator programme release (Aug 2025)","url":"https://www.enec.ae/careers-and-scholarships/talent-pipeline-programs/"}]'::jsonb, 'active', true, '2025-06-01T09:00:00Z', '2026-09-15T09:00:00Z'),
('rt-dnt-workplace', 'dnt', 'p-training-mgr', 'Diploma in Nuclear Technology: work-based placements', 'دبلوم التقنية النووية: التدريب في بيئة العمل', 'The work-based part of the 24-month DNT: placements in the maintenance workshop, the chemistry laboratory, radiation protection and field operations, leading towards Local Operator or Maintenance Technician roles.', 'الجزء العملي من دبلوم التقنية النووية الممتد 24 شهراً: تدريب في ورشة الصيانة ومختبر الكيمياء والوقاية من الإشعاع والعمليات الميدانية، تمهيداً لوظيفتي المشغّل المحلي أو فني الصيانة.', 12, 24, '[{"seq":1,"family_id":"maintenance","host_team_en":"Mechanical maintenance workshop","host_team_ar":"ورشة الصيانة الميكانيكية","host_role_id":"maintenance-technician-engineer","host_manager_id":"p-work-control","host_name_en":"Execution Supervisor · Work Control (role card)","host_name_ar":"مشرف التنفيذ · التحكم في الأعمال (بطاقة دور)","months":4,"site_induction":true,"objectives":[{"id":"o1-1","skill_id":"sk-mp-01-mech","level":2,"text_en":"Complete supervised pump and valve maintenance tasks","text_ar":"إكمال مهام صيانة المضخات والصمامات تحت الإشراف"},{"id":"o1-2","skill_id":"sk-hu-01-star","level":1,"text_en":"Apply procedure use and adherence on every task","text_ar":"تطبيق استخدام الإجراءات والالتزام بها في كل مهمة"}]},{"seq":2,"family_id":"chemistry","host_team_en":"Chemistry laboratory","host_team_ar":"مختبر الكيمياء","host_role_id":"chemistry-technician","host_manager_id":"p-chem-sup","host_name_en":"Chemistry Supervisor (role card)","host_name_ar":"مشرف الكيمياء (بطاقة دور)","months":2,"site_induction":true,"objectives":[{"id":"o2-1","skill_id":"sk-ch-02-labqa","level":1,"text_en":"Run laboratory quality-control checks","text_ar":"إجراء فحوصات ضبط الجودة في المختبر"},{"id":"o2-2","skill_id":"sk-ch-01","level":1,"text_en":"Explain why each primary-chemistry parameter is controlled","text_ar":"شرح سبب ضبط كل معامل من معاملات كيمياء الدائرة الأولية"}]},{"seq":3,"family_id":"radiation-protection","host_team_en":"Radiation protection","host_team_ar":"الوقاية من الإشعاع","host_role_id":"radiation-protection-technician","host_manager_id":"p-rp-lead","host_name_en":"Radiation Protection Team Leader (role card)","host_name_ar":"قائد فريق الوقاية من الإشعاع (بطاقة دور)","months":2,"site_induction":true,"objectives":[{"id":"o3-1","skill_id":"sk-rp-02-survey","level":1,"text_en":"Perform contamination surveys with a technician","text_ar":"إجراء مسوحات التلوث مع فني"},{"id":"o3-2","skill_id":"sk-rp-01-dose","level":1,"text_en":"Compare planned and actual dose for a work package","text_ar":"مقارنة الجرعة المخططة والفعلية لحزمة عمل"}]},{"seq":4,"family_id":"operations","host_team_en":"Field operations, Crew B","host_team_ar":"العمليات الميدانية، الطاقم ب","host_role_id":"local-operator","host_manager_id":"p-sro","host_name_en":"Shift Manager · licensed SRO, Crew B (role card)","host_name_ar":"مدير الوردية · مشغّل أول مرخّص، الطاقم ب (بطاقة دور)","months":4,"site_induction":true,"objectives":[{"id":"o4-1","skill_id":"sk-co-01-rounds","level":1,"text_en":"Shadow and then perform operator rounds","text_ar":"مرافقة ثم تنفيذ جولات المشغّل"},{"id":"o4-2","skill_id":"sk-hu-02-brief","level":1,"text_en":"Contribute to pre-job briefs","text_ar":"المساهمة في إحاطات ما قبل العمل"}]}]'::jsonb, '{}'::text[], '[{"id":"enec-dnt-launch","label":"ENEC · DNT launched (Aug 2023)","url":"https://www.enec.ae/news/operations-press-releases/diploma-in-nuclear-technology-launched-to-boost-access-to-careers-in-growing-uae-nuclear-sector-for-emirati-youth/"},{"id":"enec-dnt-grad","label":"ENEC · First DNT cohort graduates (17 Jun 2026)","url":"https://www.enec.ae/en/news/latest-news/enec-celebrates-graduation-of-first-national-cohort-from-diploma-in-nuclear-technology-program/"}]'::jsonb, 'active', true, '2025-06-01T09:00:00Z', '2026-09-15T09:00:00Z'),
('rt-cross-ops-eng', 'cross_functional', 'p-chco', 'Cross-functional move: operations to plant engineering', 'انتقال متعدد الوظائف: من العمليات إلى هندسة المحطة', 'For licensed and experienced operators exploring engineering: twelve months in plant engineering and outage planning, so a later move is deliberate and evidence-based rather than a leap.', 'للمشغّلين المرخّصين وذوي الخبرة الراغبين في استكشاف الهندسة: اثنا عشر شهراً في هندسة المحطة وتخطيط الانقطاعات، ليكون أي انتقال لاحق مدروساً ومبنياً على أدلة لا قفزة في المجهول.', 6, 18, '[{"seq":1,"family_id":"engineering","host_team_en":"Plant engineering: system performance","host_team_ar":"هندسة المحطة: أداء الأنظمة","host_role_id":"systems-design-plant-engineer","host_manager_id":"p-ops-ceo","host_name_en":"CEO, ENEC Operations (role card)","host_name_ar":"الرئيس التنفيذي لـENEC للعمليات (بطاقة دور)","months":6,"site_induction":true,"objectives":[{"id":"o1-1","skill_id":"sk-en-01-mods","level":2,"text_en":"Own the operations review of two design changes","text_ar":"تولّي مراجعة العمليات لتعديلين تصميميين"},{"id":"o1-2","skill_id":"sk-en-02-perf","level":2,"text_en":"Build a performance trend for one system","text_ar":"إعداد اتجاه أداء لنظام واحد"},{"id":"o1-3","skill_id":"sk-da-01-analysis","level":1,"text_en":"Use exported plant data for one engineering question","text_ar":"استخدام بيانات المحطة المصدّرة للإجابة عن سؤال هندسي"}]},{"seq":2,"family_id":"outage","host_team_en":"Outage planning","host_team_ar":"تخطيط الانقطاعات","host_role_id":"outage-manager-planner","host_manager_id":"p-outage-manager","host_name_en":"Outage Manager (role card)","host_name_ar":"مدير فترات الإيقاف (بطاقة دور)","months":6,"site_induction":true,"objectives":[{"id":"o2-1","skill_id":"sk-mp-01-outage","level":2,"text_en":"Plan the operations scope of one outage window","text_ar":"تخطيط نطاق العمليات لنافذة انقطاع واحدة"},{"id":"o2-2","skill_id":"sk-en-01-project","level":1,"text_en":"Track milestones for an outage modification","text_ar":"متابعة مراحل تعديل خلال الانقطاع"}]}]'::jsonb, array['operations']::text[], '[]'::jsonb, 'active', true, '2025-06-01T09:00:00Z', '2026-09-15T09:00:00Z'),
('rt-hipo-leadership', 'hipo', 'p-chco', 'High-potential leadership rotation', 'تناوب القيادة لأصحاب الإمكانات العالية', 'Twelve months across the corrective action programme, emergency preparedness and training, for people identified in talent review. Each placement has leadership and safety-culture objectives that the host signs off.', 'اثنا عشر شهراً في برنامج الإجراءات التصحيحية والتأهب للطوارئ والتدريب، للموظفين الذين حُدّدوا في مراجعة المواهب. لكل تناوب أهداف في القيادة وثقافة السلامة يعتمدها المضيف.', 9, 15, '[{"seq":1,"family_id":"oversight","host_team_en":"Corrective action programme","host_team_ar":"برنامج الإجراءات التصحيحية","host_role_id":"nuclear-oversight-npi","host_manager_id":"p-cap-chair","host_name_en":"CAP Screening Committee chair (role card)","host_name_ar":"رئيس لجنة فرز الإجراءات التصحيحية (بطاقة دور)","months":4,"site_induction":false,"objectives":[{"id":"o1-1","skill_id":"sk-hu-01","level":2,"text_en":"Screen condition reports with the committee","text_ar":"فحص تقارير الحالة مع اللجنة"},{"id":"o1-2","skill_id":"sk-sc-02","level":2,"text_en":"Lead one apparent-cause evaluation","text_ar":"قيادة تقييم سبب ظاهري واحد"}]},{"seq":2,"family_id":"emergency-preparedness","host_team_en":"Emergency preparedness","host_team_ar":"التأهب للطوارئ","host_role_id":"emergency-preparedness-coordinator","host_manager_id":"p-ep-manager","host_name_en":"Emergency Preparedness Manager (role card)","host_name_ar":"مدير التأهب للطوارئ (بطاقة دور)","months":4,"site_induction":true,"objectives":[{"id":"o2-1","skill_id":"sk-ep-01-ero","level":2,"text_en":"Fill an emergency-response organisation position in a drill","text_ar":"شغل موقع في منظمة الاستجابة للطوارئ خلال تمرين"},{"id":"o2-2","skill_id":"sk-ld-02-decide","level":2,"text_en":"Make and record time-critical decisions in an exercise","text_ar":"اتخاذ قرارات حرجة زمنياً وتسجيلها في تمرين"}]},{"seq":3,"family_id":"training","host_team_en":"Training and coaching","host_team_ar":"التدريب والتوجيه","host_role_id":"nuclear-training-instructor","host_manager_id":"p-training-mgr","host_name_en":"Training Manager (role card)","host_name_ar":"مدير التدريب (بطاقة دور)","months":4,"site_induction":false,"objectives":[{"id":"o3-1","skill_id":"sk-ld-01-coach","level":2,"text_en":"Coach two junior colleagues for a quarter","text_ar":"توجيه زميلين مبتدئين لمدة ربع سنة"},{"id":"o3-2","skill_id":"sk-ld-01-instruct","level":1,"text_en":"Co-deliver one classroom session","text_ar":"المشاركة في تقديم جلسة صفية واحدة"}]}]'::jsonb, '{}'::text[], '[]'::jsonb, 'active', true, '2025-06-01T09:00:00Z', '2026-09-15T09:00:00Z'),
('rt-digital-draft', 'cross_functional', 'p-chco', 'Digital and data rotation (draft)', 'تناوب الرقمنة والبيانات (مسودة)', 'Draft: six months for people moving into data roles, starting in work-control data and continuing with the governed AI review pilot. Hosts to be confirmed before publishing.', 'مسودة: ستة أشهر لمن ينتقلون إلى أدوار البيانات، تبدأ ببيانات مراقبة الأعمال وتستمر مع تجربة مراجعة الذكاء الاصطناعي المحوكم. يُؤكَّد المضيفون قبل النشر.', 6, 12, '[{"seq":1,"family_id":"operations","host_team_en":"Work control data","host_team_ar":"بيانات مراقبة الأعمال","host_role_id":"operations-support-work-control","host_manager_id":"p-work-control","host_name_en":"Execution Supervisor · Work Control (role card)","host_name_ar":"مشرف التنفيذ · التحكم في الأعمال (بطاقة دور)","months":3,"site_induction":false,"objectives":[{"id":"o1-1","skill_id":"sk-da-01-analysis","level":2,"text_en":"Analyse backlog data for one quarter","text_ar":"تحليل بيانات الأعمال المتراكمة لربع سنة"}]},{"seq":2,"family_id":"outage","host_team_en":"Governed AI review pilot","host_team_ar":"تجربة مراجعة الذكاء الاصطناعي المحوكم","host_role_id":"outage-manager-planner","host_manager_id":"p-outage-manager","host_name_en":"Outage Manager (role card)","host_name_ar":"مدير فترات الإيقاف (بطاقة دور)","months":3,"site_induction":false,"objectives":[{"id":"o2-1","skill_id":"sk-da-02-review","level":2,"text_en":"Review AI-drafted summaries against source records","text_ar":"مراجعة الملخصات المُعدّة آلياً مقابل السجلات الأصلية"}]}]'::jsonb, '{}'::text[], '[]'::jsonb, 'draft', false, '2025-06-01T09:00:00Z', '2026-09-15T09:00:00Z')
