insert into kafaa_leadership_programmes (id, code, kind, title_en, title_ar, summary_en, summary_ar, audience_en, audience_ar, duration_en, duration_ar, duration_days, completions, completions_year, fact_en, fact_ar, steps, mandatory_steps, required_tracks, skill_ids, behaviour_ids, nominable, course_id, link_route, sources, sort) values
('prog-intilaqa', 'INTILAQA', 'course', 'INTILAQA: first-line leadership', 'انطلاقة: قيادة الخط الأول', 'The mandatory first-line leadership programme that introduces new leaders to the foundational skills needed to lead their teams effectively in the nuclear environment.', 'برنامج قيادة الخط الأول الإلزامي الذي يعرّف القادة الجدد بالمهارات الأساسية اللازمة لقيادة فرقهم بفعالية في البيئة النووية.', 'New first-line leaders (mandatory). Reactor operators and senior reactor operators take it as Leading Effective Teams (LET).', 'قادة الخط الأول الجدد (إلزامي). يلتحق به مشغلو المفاعل والمشغلون الأوائل بصيغة قيادة الفرق الفعّالة (LET).', '4 days', '4 أيام', 4, 285, 2024, 'Completed by 285 leaders in 2024 (per source).', 'أكمله 285 قائداً في 2024 (وفق المصدر).', array['first_line']::text[], array['first_line']::text[], array['shift']::text[], array['sk-ld-01','sk-ld-01-coach','sk-sc-02','sk-hu-02-brief']::text[], array['b-safety-values','b-communication','b-respect']::text[], true, 'c-intilaqa', null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 10),
('prog-let', 'LET', 'course', 'Leading Effective Teams (LET)', 'قيادة الفرق الفعّالة (LET)', 'The INTILAQA first-line leadership content as delivered to reactor operators and senior reactor operators, who lead crews in the control room.', 'محتوى برنامج انطلاقة لقيادة الخط الأول كما يُقدَّم لمشغلي المفاعل والمشغلين الأوائل الذين يقودون الطواقم في غرفة التحكم.', 'Reactor operators and senior reactor operators (shift supervisor track: required).', 'مشغلو المفاعل والمشغلون الأوائل (مسار مشرف الوردية: إلزامي).', 'INTILAQA format', 'بصيغة برنامج انطلاقة', null, null, null, 'ROs and SROs are trained through LET (per source).', 'يتدرب مشغلو المفاعل والمشغلون الأوائل عبر برنامج LET (وفق المصدر).', array['first_line']::text[], '{}'::text[], array['shift']::text[], array['sk-ld-01','sk-ld-01-coach','sk-ld-02','sk-sc-02']::text[], array['b-safety-values','b-decisions','b-communication']::text[], true, 'c-intilaqa', null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 20),
('prog-estadad', 'ESTADAD', 'programme', 'ESTADAD: high-potential development', 'استعداد: تطوير أصحاب الإمكانات العالية', 'A professional development initiative that equips high-potential nuclear safety contributors with skills for leadership and continuous improvement: self-management, accountability, change management, effective communication and a strategic mindset.', 'مبادرة للتطوير المهني تزوّد أصحاب الإمكانات العالية من المساهمين في السلامة النووية بمهارات القيادة والتحسين المستمر: إدارة الذات والمساءلة وإدارة التغيير والتواصل الفعّال والتفكير الاستراتيجي.', 'High-potential individual contributors, by nomination.', 'المساهمون الأفراد أصحاب الإمكانات العالية، بالترشيح.', '8 days', '8 أيام', 8, 62, 2024, 'Completed by 62 leaders in 2024 (per source).', 'أكمله 62 قائداً في 2024 (وفق المصدر).', array['ic','first_line']::text[], '{}'::text[], '{}'::text[], array['sk-ld-01','sk-ld-02','sk-ld-02-decide','sk-sc-01']::text[], array['b-accountability','b-learning','b-communication']::text[], true, 'c-estadad', null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 30),
('prog-hipo-coaching', 'HIPO-COACH', 'coaching', 'Coaching for high-potential employees', 'الإرشاد لأصحاب الإمكانات العالية', 'Coaching embedded in ESTADAD for high-potential employees identified by senior leaders in the 9-box review, to encourage reflection, collaboration and collective growth.', 'إرشاد ضمن برنامج استعداد للموظفين أصحاب الإمكانات العالية الذين يحددهم كبار القادة في مراجعة المصفوفة التساعية، لتشجيع التأمل والتعاون والنمو الجماعي.', 'High-potential individual contributors identified in the 9-box review (not by application).', 'المساهمون الأفراد أصحاب الإمكانات العالية المحددون في مراجعة المصفوفة التساعية (ليس بالتقديم).', 'Part of ESTADAD', 'جزء من برنامج استعداد', null, 90, 2024, 'Over 90 employees took part across four ESTADAD cohorts in 2024 (per source).', 'شارك أكثر من 90 موظفاً عبر أربع دفعات من برنامج استعداد في 2024 (وفق المصدر).', array['ic']::text[], '{}'::text[], '{}'::text[], array['sk-ld-01-coach','sk-sc-01']::text[], array['b-learning','b-accountability']::text[], false, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 40),
('prog-fas', 'FAS', 'programme', 'Foundational Alignment Session (FAS)', 'جلسة المواءمة التأسيسية (FAS)', 'Two one-day sessions that make sure front-line leaders are fully informed of leadership gaps in the nuclear field and discuss how to tackle them as nuclear business leaders.', 'جلستان مدة كل منهما يوم واحد لضمان اطلاع قادة الخط الأمامي على فجوات القيادة في المجال النووي ومناقشة سبل معالجتها بصفتهم قادة أعمال نووية.', 'Front-line leaders.', 'قادة الخط الأمامي.', 'Two one-day sessions', 'جلستان مدة كل منهما يوم واحد', 2, 419, 2024, 'Completed by 419 leaders in 2024 (per source).', 'أكمله 419 قائداً في 2024 (وفق المصدر).', array['first_line']::text[], '{}'::text[], '{}'::text[], array['sk-sc-02','sk-ld-02']::text[], array['b-safety-values','b-concerns']::text[], true, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 50),
('prog-cld', 'CLD', 'programme', 'Continuous Leadership Development (CLD)', 'التطوير القيادي المستمر (CLD)', 'Two one-day sessions for managers and directors on leadership gaps in the nuclear field and how to tackle them.', 'جلستان مدة كل منهما يوم واحد للمديرين وكبار المديرين حول فجوات القيادة في المجال النووي وسبل معالجتها.', 'Managers and directors.', 'المديرون وكبار المديرين.', 'Two one-day sessions', 'جلستان مدة كل منهما يوم واحد', 2, 326, 2024, 'Completed by 326 leaders in 2024 (per source).', 'أكمله 326 قائداً في 2024 (وفق المصدر).', array['manager','director']::text[], '{}'::text[], '{}'::text[], array['sk-ld-01','sk-sc-02']::text[], array['b-safety-values','b-learning']::text[], true, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 60),
('prog-one', 'ONE', 'programme', 'Onwards to Nuclear Excellence (ONE)', 'نحو التميز النووي (ONE)', 'A transformational programme for nominated managers and directors that aims to improve station performance, employee engagement and nuclear safety through collaboration, a growth mindset, neuroscience and leadership roles.', 'برنامج تحوّلي للمديرين وكبار المديرين المرشحين يهدف إلى تحسين أداء المحطة وتفاعل الموظفين والسلامة النووية من خلال التعاون وعقلية النمو وعلم الأعصاب والأدوار القيادية.', 'Nominated managers and directors.', 'المديرون وكبار المديرين المرشحون.', '3 weeks', '3 أسابيع', 15, 52, 2024, 'Completed by 52 leaders in 2024 (per source).', 'أكمله 52 قائداً في 2024 (وفق المصدر).', array['manager','director']::text[], '{}'::text[], '{}'::text[], array['sk-ld-01','sk-ld-01-coach','sk-ld-02','sk-sc-02']::text[], array['b-safety-values','b-respect','b-learning']::text[], true, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 70),
('prog-masterclass', 'MASTERCLASS', 'programme', 'Executive leadership master classes', 'الدروس المتقدمة للقيادة التنفيذية', 'Master classes for executive leaders on organisational culture and the behaviours needed to fulfil the organisation''s vision.', 'دروس متقدمة للقادة التنفيذيين حول ثقافة المؤسسة والسلوكيات اللازمة لتحقيق رؤيتها.', 'Executive leadership.', 'القيادة التنفيذية.', 'Master class series', 'سلسلة دروس متقدمة', null, 32, 2024, 'Completed by 32 leaders in 2024 (per source).', 'أكملها 32 قائداً في 2024 (وفق المصدر).', array['director','executive']::text[], '{}'::text[], '{}'::text[], array['sk-sc-02','sk-ld-02']::text[], array['b-safety-values','b-respect']::text[], true, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 80),
('prog-inpo', 'INPO', 'external', 'INPO leadership courses (Atlanta)', 'دورات القيادة لدى معهد INPO (أتلانتا)', 'Seven nuclear-specific leadership courses of various lengths at the Institute of Nuclear Power Operations in Atlanta, for nominated leaders, aligned with industry best practice for nuclear safety and operational excellence.', 'سبع دورات قيادية متخصصة في المجال النووي بمدد مختلفة لدى معهد عمليات الطاقة النووية (INPO) في أتلانتا، للقادة المرشحين، وفق أفضل ممارسات القطاع في السلامة النووية والتميز التشغيلي.', 'Nominated leaders.', 'القادة المرشحون.', 'Various lengths', 'مدد مختلفة', null, 19, 2024, '19 leaders completed these courses in 2024 (per source).', 'أكمل 19 قائداً هذه الدورات في 2024 (وفق المصدر).', array['manager','director','executive']::text[], '{}'::text[], '{}'::text[], array['sk-ld-02','sk-sc-02','sk-ld-02-decide']::text[], array['b-safety-values','b-decisions']::text[], true, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 90),
('prog-exec-coaching', 'EXEC-COACH', 'coaching', 'Executive Coaching Program', 'برنامج الإرشاد التنفيذي', 'Personalised coaching for mid-level and executive managers with external certified coaches, to prepare them for strategic roles.', 'إرشاد مخصص للمديرين في المستويين المتوسط والتنفيذي مع مرشدين خارجيين معتمدين، لإعدادهم للأدوار الاستراتيجية.', 'Mid-level and executive managers (chiefs, VPs and directors).', 'المديرون في المستويين المتوسط والتنفيذي (الرؤساء ونواب الرئيس والمديرون).', 'Ongoing coaching sessions', 'جلسات إرشاد مستمرة', null, 15, null, '15 senior leaders take part; over 55 sessions since Q4 2024, as of March 2025 (per source).', 'يشارك 15 من كبار القادة؛ وعُقدت أكثر من 55 جلسة منذ الربع الأخير من 2024 حتى مارس 2025 (وفق المصدر).', array['director','executive']::text[], '{}'::text[], '{}'::text[], array['sk-ld-01-coach','sk-ld-02']::text[], array['b-accountability','b-decisions']::text[], true, null, null, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 100),
('prog-mentoring', 'LEAD-MENTOR', 'mentoring', 'Leadership mentoring programme', 'برنامج الإرشاد القيادي', 'Pairs senior leaders with emerging talent to transfer knowledge, organisational values and expertise. Request a mentor in Kafa''a mentoring.', 'يجمع كبار القادة مع المواهب الصاعدة لنقل المعرفة وقيم المؤسسة والخبرة. اطلب مرشداً من صفحة الإرشاد في كفاءة.', 'Emerging talent and first-line leaders.', 'المواهب الصاعدة وقادة الخط الأول.', 'Mentoring agreement', 'اتفاقية إرشاد', null, null, null, 'Part of the coaching and mentoring programmes for top talent (per source).', 'جزء من برامج الإرشاد والتوجيه لأفضل المواهب (وفق المصدر).', array['ic','first_line']::text[], '{}'::text[], '{}'::text[], array['sk-ld-01-coach','sk-sc-01']::text[], array['b-learning','b-concerns']::text[], false, null, '/my/mentoring', '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb, 110)
